#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_2 2
#define GPIO_3 3
#define INTERVAL 2

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    const char *chip_name = "gpiochip0";
    struct gpiod_chip *chip;
    struct gpiod_line *line2, *line3;
    int ret;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get lines by number
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        perror("Failed to get line 2");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        perror("Failed to get line 3");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines as outputs
    ret = gpiod_line_request_output(line2, "output2", 0);
    if (ret) {
        perror("Failed to request line 2 as output");
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line3, "output3", 0);
    if (ret) {
        perror("Failed to request line 3 as output");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        // Toggle line 2
        ret = gpiod_line_set_value(line2, !gpiod_line_get_value(line2));
        if (ret) {
            perror("Failed to set line 2 value");
            break;
        }

        // Toggle line 3
        ret = gpiod_line_set_value(line3, !gpiod_line_get_value(line3));
        if (ret) {
            perror("Failed to set line 3 value");
            break;
        }

        // Report current state
        printf("Line 2: %s, Line 3: %s\n",
               gpiod_line_get_value(line2) ? "High" : "Low",
               gpiod_line_get_value(line3) ? "High" : "Low");

        // Sleep for 2 seconds
        sleep(INTERVAL);
    }

    // Release lines and close chip
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
