#define ADS1115_PGA_4P096V 0x01
#define ADS1115_PGA_2P048V 0x02
#define ADS1115_PGA_1P024V 0x03
#define ADS1115_PGA_0P512V 0x04
#define ADS1115_PGA_0P256V 0x05
#define ADS1115_PGA_0P128V 0x06
#define ADS1115_PGA_0P064V 0x07

#define ADS1115_DR_8SPS 0x00
#define ADS1115_DR_16SPS 0x01
#define ADS1115_DR_32SPS 0x02
#define ADS1115_DR_64SPS 0x03
#define ADS1115_DR_128SPS 0x04
#define ADS1115_DR_250SPS 0x05
