#define ADS1115_DR_920SPS 0x07
#define ADS1115_DR_1600SPS 0x08
#define ADS1115_DR_3300SPS 0x09
#define ADS1115_DR_6400SPS 0x0A
#define ADS1115_DR_12800SPS 0x0B

#define ADS1115_MODE_MASK 0x03
#define ADS1115_GAIN_MASK 0x0F
#define ADS1115_DATA_RATE_MASK 0x0F
#define ADS1115_CHANNEL_MASK 0x03
#define ADS1115_PGA_MASK 0x07
#define ADS1115_DR_MASK 0x0F

#define ADS1115_CONFIG_DEFAULT (ADS1115_MODE_CONTINUOUS | ADS1115_GAIN_1X | ADS1115_DATA_RATE_128SPS | ADS1115_CHANNEL_0)

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int i2c_fd;
    int gpio_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    uint8_t config;
    uint16_t data;
    struct timespec sleep_time;

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set up GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up GPIO line for interrupt
    line = gpiod_chip_get_line(chip, 17); // Example GPIO pin for interrupt
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request a line as input
    if (gpiod_line_request_input(line, "ads1115_irq")) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up configuration register
    config = ADS1115_CONFIG_DEFAULT;
    if (ioctl(i2c_fd, I2C_SMBUS_WRITE_BYTE_DATA, ADS1115_REG_CONFIG, config) < 0) {
        perror("Failed to write configuration register");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Wait for interrupt
        if (gpiod_line_event_wait(line, &sleep_time) < 0) {
            perror("Failed to wait for interrupt");
            break;
        }

        // Read conversion result
        if (ioctl(i2c_fd, I2C_SMBUS_READ_WORD_DATA, ADS1115_REG_CONVERSION) < 0) {
            perror("Failed to read conversion result");
            break;
        }

        // Read data from I2C buffer
        if (read(i2c_fd, &data, sizeof(data)) != sizeof(data)) {
            perror("Failed to read data from I2C buffer");
            break;
        }

        // Print the reading
        printf("ADC Reading: %d\n", data);

        // Sleep for 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

