int main() {
    const char *i2c_dev = "/dev/i2c-1"; // Adjust based on your Raspberry Pi model
    const char *gpio_irq = "gpio17"; // Adjust based on your Raspberry Pi model

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(gpio_irq);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request IRQ line
    irq_line = gpiod_chip_get_line(gpio_chip, 0);
    if (!irq_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request IRQ event
    if (gpiod_line_request_edge_event(irq_line, "mlx90614", GPIOD_EDGE_RISING)) {
        perror("Failed to request IRQ event");
        gpiod_line_release(irq_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t temp_raw;
        ssize_t bytes_read;

        // Read temperature data from MLX90614
        bytes_read = read(i2c_fd, &temp_raw, sizeof(temp_raw));
        if (bytes_read != sizeof(temp_raw)) {
            if (errno == EAGAIN) {
                printf("No data available, retrying...\n");
                usleep(100000); // Wait for 100ms
                continue;
            } else {
                perror("Failed to read temperature data");
                break;
            }
        }

        // Convert raw temperature to Celsius
        float temp_celsius = (temp_raw - 0x3F80) * MLX90614_TEMP_RESOLUTION;

        // Print temperature
        printf("Temperature: %.2f°C\n", temp_celsius);

        // Wait for 5 seconds
        sleep(5);
    }

    // Release resources
    gpiod_line_release(irq_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

