int main() {
    int channel = ADS1115_CHANNEL_0; // Change this to the desired channel
    int gain = ADS1115_GAIN_1X; // Change this to the desired gain
    int data_rate = ADS1115_DATA_RATE_128; // Change this to the desired data rate

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO chip
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set up GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, 17); // Change this to the desired GPIO pin
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Request a line as output
    if (gpiod_line_request_output(gpio_line, "ADS1115", 0)) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set up ADS1115 configuration register
    uint16_t config = (ADS1115_MODE_CONTINUOUS << 15) |
                      (gain << 12) |
                      (data_rate << 3) |
                      (channel << 0);

    if (ioctl(i2c_fd, I2C_SMBUS_WRITE_BYTE_DATA, ADS1115_REG_CONFIG, config) < 0) {
        perror("Failed to write configuration register");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Read conversion result
        uint16_t conversion = 0;
        if (ioctl(i2c_fd, I2C_SMBUS_READ_WORD_DATA, ADS1115_REG_CONVERSION, &conversion) < 0) {
            perror("Failed to read conversion result");
