#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_DUTYCYCLE 50

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int result;

    // Initialize pigpio library
    result = gpioInitialise();
    if (result < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioErrDescription(result));
        return EXIT_FAILURE;
    }

    // Set up PWM on GPIO 18
    result = gpioSetPWMFrequency(PWM_PIN, PWM_FREQ);
    if (result < 0) {
        fprintf(stderr, "Failed to set PWM frequency: %s\n", gpioErrDescription(result));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    result = gpioSetPWMRange(PWM_PIN, 1023);
    if (result < 0) {
        fprintf(stderr, "Failed to set PWM range: %s\n", gpioErrDescription(result));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    while (keep_running) {
        // Apply different duty cycle values
        for (int duty_cycle = 0; duty_cycle <= 1023; duty_cycle += 10) {
            result = gpioPWM(PWM_PIN, duty_cycle);
            if (result < 0) {
                fprintf(stderr, "Failed to set PWM duty cycle: %s\n", gpioErrDescription(result));
                break;
            }
            printf("Duty Cycle: %d\n", duty_cycle);
            sleep(0.5);
        }
    }

    // Clean up resources
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define TIMEOUT_MS 5000

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    const char *chip_name = "gpiochip0";
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    int trigger_value, echo_value;
    uint64_t timeout_ns = TIMEOUT_MS * 1000000;
    struct timespec start_time, end_time;
    double duration_ms;
    int distance_cm;

    // Register signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Get the trigger and echo lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the trigger and echo lines for output
    if (gpiod_line_request_output(trigger_line, "trigger", 0)) {
        perror("Failed to request trigger line");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(echo_line, "echo")) {
        perror("Failed to request echo line");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        // Send a pulse to the trigger pin
        trigger_value = 1;
        if (gpiod_line_set_value(trigger_line, trigger_value)) {
            perror("Failed to set trigger line high");
            continue;
        }
        usleep(10); // Wait for 10 microseconds
        trigger_value = 0;
        if (gpiod_line_set_value(trigger_line, trigger_value)) {
            perror("Failed to set trigger line low");
            continue;
        }

        // Wait for the echo signal to return
        if (gpiod_line_event_wait(echo_line, &timeout_ns, NULL)) {
            perror("Echo line event wait timed out");
            continue;
        }

        // Read the echo value
        if (gpiod_line_get_value(echo_line, &echo_value)) {
            perror("Failed to read echo line");
            continue;
        }

        // Calculate the duration of the pulse
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        while (!gpiod_line_event_wait(echo_line, &timeout_ns, NULL)) {
            if (should_exit) {
                break;
            }
        }
        clock_gettime(CLOCK_MONOTONIC, &end_time);

        duration_ms = (end_time.tv_sec - start_time.tv_sec) * 1000.0 +
                      (end_time.tv_nsec - start_time.tv_nsec) / 1000000.0;

        // Calculate the distance in centimeters
        distance_cm = (duration_ms / 2.0) * 343.0; // Speed of sound in cm/s

        // Print the distance
        printf("Distance: %.2f cm\n", distance_cm);

        // Wait for 60 seconds before the next measurement
        sleep(60);
    }

    // Release the lines and close the chip
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

