static struct gpiod_line *alert_line;

void signal_handler(int signum) {
    printf("Received signal %d, exiting...\n", signum);
    close(i2c_fd);
    gpiod_line_release(alert_line);
    gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int read_adc_channel(int channel) {
    uint16_t config = ADS1115_MODE_CONTINUOUS | ADS1115_GAIN_1X | ADS1115_DATA_RATE_128SPS | (channel << 4);
    uint16_t data;

    // Write configuration register
    if (write(i2c_fd, &config, sizeof(config)) != sizeof(config)) {
        perror("Failed to write configuration register");
        return -1;
    }

    // Wait for conversion to complete
    while ((read(i2c_fd, &data, sizeof(data))) != sizeof(data)) {
        if (errno == EAGAIN) {
            usleep(1000);
        } else {
            perror("Failed to read conversion result");
            return -1;
        }
    }

    // Check for alert flag
    uint16_t status;
    if (read(i2c_fd, &status, sizeof(status)) != sizeof(status)) {
        perror("Failed to read alert status");
        return -1;
    }

    if (status & ADS1115_ALERT_FLAG) {
        printf("Alert flag set, ignoring reading\n");
        return -1;
    }

    return data;
}

int main() {
    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    alert_line = gpiod_chip_get_line(chip, 17); // Assuming ALERT pin is GPIO17
    if (!alert_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(alert_line, "ADS1115_ALERT");
    if (ret) {
        perror("Failed to request GPIO line input");
        gpiod_line_release(alert_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_release(alert_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_line_release(alert_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Sampling ADS1115 channel 0 every 5 seconds...\n");

    while (1) {
        int reading = read_adc_channel(ADS1115_CHANNEL_0);
        if (reading >= 0) {
            printf("ADC Channel 0: %d\n", reading);
        } else {
            printf("Failed to read ADC channel 0\n");
        }

        sleep(5);
    }

    // Close resources
    close(i2c_fd);
    gpiod_line_release(alert_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

