    }

    // Request input direction for GPIO line
    if (gpiod_line_request_input(gpio_line, "ads1115_irq")) {
        perror("Failed to request input direction for GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up interrupt event
    if (gpiod_line_event_add(gpio_line, GPIOD_LINE_EVENT_RISING_EDGE)) {
        perror("Failed to add rising edge event");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up ADS1115 configuration
    uint8_t config = ADS1115_CONFIG_DEFAULT;
    if (ioctl(i2c_fd, I2C_SMBUS_WRITE_BYTE_DATA, ADS1115_REG_CONFIG, config) < 0) {
        perror("Failed to write configuration to ADS1115");
        cleanup();
        return EXIT_FAILURE;
    }

    // Read data continuously
    while (1) {
        uint8_t data[2];
        if (ioctl(i2c_fd, I2C_SMBUS_READ_BLOCK_DATA, ADS1115_REG_CONVERSION, data, 2) < 0) {
            perror("Failed to read conversion data from ADS1115");
            cleanup();
            return EXIT_FAILURE;
        }

        // Calculate the raw value
        int16_t raw_value = (data[0] << 8) | data[1];

        // Print the raw value
        printf("Raw value: %d\n", raw_value);

        // Wait for the next conversion
        usleep(1000000 / 128); // 128 samples per second
    }

    // Cleanup on exit
    cleanup();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_2 2
#define GPIO_3 3
#define INTERVAL 5

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int fd_gpio2, fd_gpio3;
    struct gpiod_chip *chip;
    struct gpiod_line *line2, *line3;
    enum gpiod_line_value value2, value3;

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    // Open lines
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        perror("Failed to get line 2");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        perror("Failed to get line 3");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines as outputs
    if (gpiod_line_request_output(line2, "gpio2", 0)) {
        perror("Failed to request line 2 as output");
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line3, "gpio3", 0)) {
        perror("Failed to request line 3 as output");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set initial values
    value2 = GPIOD_LINE_VALUE_LOW;
    value3 = GPIOD_LINE_VALUE_LOW;
    if (gpiod_line_set_value(line2, value2)) {
        perror("Failed to set line 2 value");
        gpiod_line_release(line3);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_set_value(line3, value3)) {
        perror("Failed to set line 3 value");
        gpiod_line_release(line3);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (!should_exit) {
        // Toggle values
        value2 = (value2 == GPIOD_LINE_VALUE_LOW) ? GPIOD_LINE_VALUE_HIGH : GPIOD_LINE_VALUE_LOW;
        value3 = (value3 == GPIOD_LINE_VALUE_LOW) ? GPIOD_LINE_VALUE_HIGH : GPIOD_LINE_VALUE_LOW;

        // Apply values
        if (gpiod_line_set_value(line2, value2)) {
            perror("Failed to set line 2 value");
            break;
        }
        if (gpiod_line_set_value(line3, value3)) {
            perror("Failed to set line 3 value");
            break;
        }

        // Report current state
        printf("GPIO 2: %s, GPIO 3: %s\n",
               (value2 == GPIOD_LINE_VALUE_LOW) ? "LOW" : "HIGH",
               (value3 == GPIOD_LINE_VALUE_LOW) ? "LOW" : "HIGH");

        // Sleep for 5 seconds
        sleep(INTERVAL);
    }

    // Clean up
    gpiod_line_release(line3);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

