#define SI7021_ADDR 0x40
#define SI7021_READ_TEMP_HOLD 0xE3
#define SI7021_READ_HUMIDITY_HOLD 0xE5
#define SI7021_READ_TEMP_NOHOLD 0xF3
#define SI7021_READ_HUMIDITY_NOHOLD 0xF5
#define SI7021_RESET 0xFE

#define BUFFER_SIZE 16

static int i2c_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;

void handle_signal(int signum) {
    printf("Received signal %d, exiting...\n", signum);
    close(i2c_fd);
    gpiod_chip_close(gpio_chip);
    exit(EXIT_SUCCESS);
}

int read_si7021_temperature() {
    uint8_t buffer[BUFFER_SIZE];
    int ret;

    // Read temperature with hold master mode
    buffer[0] = SI7021_READ_TEMP_HOLD;
    ret = write(i2c_fd, buffer, 1);
    if (ret != 1) {
        perror("Failed to write to SI7021");
        return -1;
    }

    // Wait for conversion to complete
    usleep(100000);

    // Read temperature result
    ret = read(i2c_fd, buffer, 2);
    if (ret != 2) {
        perror("Failed to read from SI7021");
        return -1;
    }

    // Calculate temperature in Celsius
    float temp_celsius = ((buffer[0] << 8) | buffer[1]) * 0.001953125;
    return (int)temp_celsius;
}

int read_si7021_humidity() {
    uint8_t buffer[BUFFER_SIZE];
    int ret;

    // Read humidity with hold master mode
    buffer[0] = SI7021_READ_HUMIDITY_HOLD;
    ret = write(i2c_fd, buffer, 1);
    if (ret != 1) {
        perror("Failed to write to SI7021");
        return -1;
    }

    // Wait for conversion to complete
    usleep(100000);

    // Read humidity result
    ret = read(i2c_fd, buffer, 2);
    if (ret != 2) {
        perror("Failed to read from SI7021");
        return -1;
    }

    // Calculate humidity in percent
    float humidity_percent = ((buffer[0] << 8) | buffer[1]) * 0.00125;
    return (int)humidity_percent;
}

