    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Request chip and line
    gpio_chip = gpiod_chip_open_by_name(gpio_chip_name);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, atoi(gpio_line_name));
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request output mode for reset line
    ret = gpiod_line_request_output(gpio_line, "si7021_reset", 0);
    if (ret) {
        perror("Failed to request GPIO line output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Reset the SI7021
    gpiod_line_set_value(gpio_line, 1);
    usleep(100000);
    gpiod_line_set_value(gpio_line, 0);

    // Set I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int temp_celsius = read_si7021_temperature();
        if (temp_celsius == -1) {
            printf("Failed to read temperature\n");
            continue;
