#define ADS1115_REG_HIGH_THRESHOLD 0x0B
#define ADS1115_REG_ALERT_STATUS 0x0C
#define ADS1115_REG_DEVICE_ID 0x0D

#define ADS1115_MODE_CONTINUOUS 0x00
#define ADS1115_MODE_SINGLE_SHOT 0x01
#define ADS1115_MODE_POWER_DOWN 0x02

#define ADS1115_GAIN_1X 0x00
#define ADS1115_GAIN_2X 0x01
#define ADS1115_GAIN_4X 0x02
#define ADS1115_GAIN_8X 0x03

#define ADS1115_DATA_RATE_128SPS 0x00
#define ADS1115_DATA_RATE_250SPS 0x01
#define ADS1115_DATA_RATE_490SPS 0x02
#define ADS1115_DATA_RATE_920SPS 0x03
#define ADS1115_DATA_RATE_1600SPS 0x04
#define ADS1115_DATA_RATE_3330SPS 0x05
#define ADS1115_DATA_RATE_6670SPS 0x06

#define ADS1115_CHANNEL_0 0x00
#define ADS1115_CHANNEL_1 0x01
#define ADS1115_CHANNEL_2 0x02
#define ADS1115_CHANNEL_3 0x03

#define ADS1115_PGA_6P144V 0x00
#define ADS1115_PGA_4P096V 0x01
#define ADS1115_PGA_2P048V 0x02
#define ADS1115_PGA_1P024V 0x03
#define ADS1115_PGA_0P512V 0x04
#define ADS1115_PGA_0P256V 0x05
#define ADS1115_PGA_0P128V 0x06
#define ADS1115_PGA_0P064V 0x07

static int i2c_fd;
static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    const char *i2c_dev = "/dev/i2c-1";
    int channel = ADS1115_CHANNEL_0;
    int gain = ADS1115_GAIN_1X;
    int data_rate = ADS1115_DATA_RATE_128SPS;
    int mode = ADS1115_MODE_CONTINUOUS;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    if ((i2c_fd = open(i2c_dev, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to set slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure ADS1115
    uint16_t config = (mode << 15) | (gain << 12) | (data_rate << 3) | channel;
    if (write(i2c_fd, &config, sizeof(config)) != sizeof(config)) {
        perror("Failed to write configuration");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Sampling analog channel %d with gain %d and data rate %d\n", channel, gain, data_rate);

    while (!should_exit) {
        // Read conversion result
        uint16_t conversion;
        if (read(i2c_fd, &conversion, sizeof(conversion)) != sizeof(conversion)) {
            perror("Failed to read conversion result");
            break;
        }

        // Print the reading
        printf("Reading: %d\n", conversion);

        // Wait for 1 second
        sleep(1);
    }

    // Release resources
    close(i2c_fd);

    return EXIT_SUCCESS;
}

