#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    const char *chip_name = "gpiochip0";
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    int trigger_value = 0;
    int echo_value = 0;
    long duration_us = 0;
    double distance_cm = 0.0;
    struct timespec sleep_time = {1, 0}; // 1 second

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines
    if (gpiod_line_request_output(trigger_line, "trigger", 0)) {
        perror("Failed to request trigger line");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo_line, "echo")) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (!should_exit) {
        // Trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        usleep(10); // Wait for 10 microseconds
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo pulse
        while ((echo_value = gpiod_line_get_value(echo_line)) == 0) {
            if (should_exit) {
                break;
            }
            usleep(10);
        }

        if (should_exit) {
            break;
        }

        long start_time = gpiod_line_get_value_timestamp_ns(echo_line, NULL);
        while ((echo_value = gpiod_line_get_value(echo_line)) == 1) {
            if (should_exit) {
                break;
            }
            usleep(10);
        }

        if (should_exit) {
            break;
        }

        long end_time = gpiod_line_get_value_timestamp_ns(echo_line, NULL);

        if (start_time == -1 || end_time == -1) {
            perror("Failed to get timestamp");
            gpiod_line_release(trigger_line);
            gpiod_line_release(echo_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        duration_us = (end_time - start_time) / 1000; // Convert to microseconds

        if (duration_us > 5000000) {
            fprintf(stderr, "Echo pulse too long\n");
            continue;
        }

        distance_cm = duration_us / 58.26; // Calculate distance in cm

        printf("Distance: %.2f cm\n", distance_cm);

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Release resources
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

