    // Set direction of lines to output
    ret = gpiod_line_request_output(line[0], "GPIO_17", 0);
    if (ret) {
        perror("Failed to set GPIO_17 direction");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line[1], "GPIO_18", 0);
    if (ret) {
        perror("Failed to set GPIO_18 direction");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line[2], "GPIO_27", 0);
    if (ret) {
        perror("Failed to set GPIO_27 direction");
        goto cleanup;
    }

    // Apply high level to all lines
    ret = gpiod_line_set_value(line[0], 1);
    if (ret) {
        perror("Failed to set GPIO_17 value");
        goto cleanup;
    }
    ret = gpiod_line_set_value(line[1], 1);
    if (ret) {
        perror("Failed to set GPIO_18 value");
        goto cleanup;
    }
    ret = gpiod_line_set_value(line[2], 1);
    if (ret) {
        perror("Failed to set GPIO_27 value");
        goto cleanup;
    }

    // Report the state
    printf("GPIO_17: High\n");
    printf("GPIO_18: High\n");
    printf("GPIO_27: High\n");

    // Wait for interrupt
    while (!should_exit) {
        sleep(1);
    }

cleanup:
    // Release lines
    gpiod_line_release(line[0]);
    gpiod_line_release(line[1]);
    gpiod_line_release(line[2]);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_2 2
#define GPIO_3 3
#define CYCLES 3
#define DELAY 5000000 // 5 seconds in microseconds

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line2, *line3;
    int ret;

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        perror("Failed to get line 2");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        perror("Failed to get line 3");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines as outputs
    ret = gpiod_line_request_output(line2, "output2", 0);
    if (ret) {
        perror("Failed to request line 2 as output");
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line3, "output3", 0);
    if (ret) {
        perror("Failed to request line 3 as output");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Starting cycle...\n");

    for (int i = 0; i < CYCLES; i++) {
        // Cycle through states: LOW -> HIGH -> LOW
        gpiod_line_set_value(line2, 0);
        gpiod_line_set_value(line3, 1);
        usleep(DELAY);
        gpiod_line_set_value(line2, 1);
        gpiod_line_set_value(line3, 0);
        usleep(DELAY);
        gpiod_line_set_value(line2, 0);
        gpiod_line_set_value(line3, 0);
        usleep(DELAY);

        printf("Cycle %d completed.\n", i + 1);
    }

    printf("Exiting...\n");

    // Release lines and close chip
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

