#define UART_DEVICE "/dev/ttyAMA0" // Change this to your UART device
#define BAUD_RATE B9600
#define BUFFER_SIZE 1024

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int fd;
    struct termios options;
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the UART device
    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Failed to open UART device");
        return EXIT_FAILURE;
    }

    // Get current options for the UART port
    if (tcgetattr(fd, &options) != 0) {
        perror("Failed to get UART options");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set baud rate
    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);

    // Set data bits
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;

    // Set parity
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;

    // Enable receiver and set local mode
    options.c_cflag |= CREAD | CLOCAL;

    // Disable hardware flow control
    options.c_cflag &= ~CRTSCTS;

    // Disable software flow control
    options.c_iflag &= ~(IXON | IXOFF | IXANY);

    // Set raw input mode
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);

    // Set non-blocking read
    options.c_cc[VTIME] = 0;
    options.c_cc[VMIN] = 1;

    // Apply new options
    if (tcsetattr(fd, TCSANOW, &options) != 0) {
        perror("Failed to set UART options");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("UART device opened successfully.\n");

    while (!should_exit) {
        bytes_read = read(fd, buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("Received: %s\n", buffer);
        } else if (bytes_read == 0) {
            printf("No data received.\n");
        } else {
            perror("Error reading from UART");
        }
    }

    printf("Exiting...\n");

    // Restore original terminal settings
    tcsetattr(fd, TCSANOW, &options);

    // Close the UART device
    close(fd);

    return EXIT_SUCCESS;
}

