#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 2
#define CYCLES 3
#define DELAY 60

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value = 0;
    char *chip_name = "gpiochip0";

    // Initialize signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the chip
    chip = gpiod_chip_open(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the line as output
    if (gpiod_line_request_output(line, "output", 0)) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    for (int i = 0; i < CYCLES; ++i) {
        printf("Cycle %d: Setting GPIO %d to %d\n", i + 1, GPIO_PIN, value);
        if (gpiod_line_set_value(line, value)) {
            perror("Failed to set GPIO line value");
        }
        sleep(DELAY);
        value = !value; // Toggle the value
    }

    // Release the line and chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

