#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_2 2
#define GPIO_3 3
#define INTERVAL 100000  // 0.1 seconds in microseconds

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int fd_gpio2, fd_gpio3;
    struct gpiod_chip *chip;
    struct gpiod_line *line2, *line3;
    unsigned int value2, value3;
    char chip_name[64];
    int ret;

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the first GPIO chip
    ret = gpiod_chip_open_by_name("gpiochip0", &chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(ret));
        return EXIT_FAILURE;
    }
    snprintf(chip_name, sizeof(chip_name), "gpiochip%d", chip->number);

    // Get lines 2 and 3
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line2 || !line3) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines for output
    ret = gpiod_line_request_output(line2, "GPIO2", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO2 as output: %s\n", gpiod_strerror(ret));
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(line3, "GPIO3", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO3 as output: %s\n", gpiod_strerror(ret));
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        // Toggle GPIO 2
        value2 = gpiod_line_get_value(line2);
        value2 = !value2;
        ret = gpiod_line_set_value(line2, value2);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO2 value: %s\n", gpiod_strerror(ret));
            break;
        }

        // Toggle GPIO 3
        value3 = gpiod_line_get_value(line3);
        value3 = !value3;
        ret = gpiod_line_set_value(line3, value3);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO3 value: %s\n", gpiod_strerror(ret));
            break;
        }

        // Report current state
        printf("GPIO2: %d, GPIO3: %d\n", value2, value3);

        // Sleep for 0.1 seconds
        usleep(INTERVAL);
    }

    // Release lines and close chip
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

