        perror("Failed to request line 4 as output");
        gpiod_line_release(line4);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(line17, "gpio17", 0);
    if (ret) {
        perror("Failed to request line 17 as output");
        gpiod_line_release(line4);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set initial values
    direction.value[0] = 0; // GPIO 4 low
    direction.value[1] = 0; // GPIO 17 low
    value.value[0] = 0; // GPIO 4 low
    value.value[1] = 0; // GPIO 17 low
    ret = gpiod_line_set_values_bulk(chip, &direction, &value);
    if (ret) {
        perror("Failed to set initial values");
        gpiod_line_release(line4);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Toggle GPIO 4 and GPIO 17
    while (!should_exit) {
        value.value[0] = !value.value[0]; // Toggle GPIO 4
        value.value[1] = !value.value[1]; // Toggle GPIO 17
        ret = gpiod_line_set_values_bulk(chip, &direction, &value);
        if (ret) {
            perror("Failed to toggle values");
            break;
        }
        printf("GPIO 4: %d, GPIO 17: %d\n", value.value[0], value.value[1]);
        sleep(1);
    }

    // Release lines and close chip
    gpiod_line_release(line4);
    gpiod_line_release(line17);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

