#define DELAY 100000 // 0.1 seconds in microseconds

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    enum gpiod_line_request_flags flags = GPIOD_LINE_REQUEST_FLAG_OUTPUT;
    unsigned int value = 0;

