#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_4 4
#define PWM_PIN_12 12
#define PWM_PIN_18 18

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    // Set up PWM on GPIO 4, 12, and 18
    if (gpioSetMode(PWM_PIN_4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", PWM_PIN_4);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_12, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", PWM_PIN_12);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", PWM_PIN_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set PWM frequency to 50 Hz
    if (gpioSetPWMfrequency(PWM_PIN_4, 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_PIN_4);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_12, 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_PIN_12);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_18, 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_PIN_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set initial duty cycle to 0%
    if (gpioSetPWMrange(PWM_PIN_4, 1023) < 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", PWM_PIN_4);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_12, 1023) < 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", PWM_PIN_12);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_18, 1023) < 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", PWM_PIN_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set initial duty cycle to 0%
    if (gpioPWM(PWM_PIN_4, 0) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", PWM_PIN_4);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN_12, 0) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", PWM_PIN_12);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN_18, 0) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", PWM_PIN_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    while (keep_running) {
        // Toggle duty cycle between 0% and 100%
        for (int duty_cycle = 0; duty_cycle <= 1023; duty_cycle += 10) {
            gpioPWM(PWM_PIN_4, duty_cycle);
            gpioPWM(PWM_PIN_12, duty_cycle);
            gpioPWM(PWM_PIN_18, duty_cycle);
            printf("Duty Cycle: %d%%\n", duty_cycle);
            usleep(1000000); // Sleep for 1 second
        }
        for (int duty_cycle = 1023; duty_cycle >= 0; duty_cycle -= 10) {
            gpioPWM(PWM_PIN_4, duty_cycle);
            gpioPWM(PWM_PIN_12, duty_cycle);
            gpioPWM(PWM_PIN_18, duty_cycle);
            printf("Duty Cycle: %d%%\n", duty_cycle);
            usleep(1000000); // Sleep for 1 second
        }
    }

    // Clean up
    gpioTerminate();

    return EXIT_SUCCESS;
}

