    should_exit = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    // Set up PWM pins
    if (gpioSetMode(PWM_PIN_17, PI_OUTPUT) != PI_OK ||
        gpioSetMode(PWM_PIN_18, PI_OUTPUT) != PI_OK ||
        gpioSetMode(PWM_PIN_27, PI_OUTPUT) != PI_OK) {
