        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set PWM frequency to 100 Hz
    if (gpioSetPWMfrequency(PWM_PIN_17, 100) != PI_OK ||
        gpioSetPWMfrequency(PWM_PIN_18, 100) != PI_OK ||
