#define W1_BUS 1
#define W1_DEVICE_PATH "/sys/bus/w1/devices/"
#define W1_DEVICE_PREFIX "28-"
#define W1_READ_FILE "w1_slave"

static int gpiod_chip = -1;
static int gpio_fd[3] = {-1, -1, -1};

void cleanup() {
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    for (int i = 0; i < 3; i++) {
        if (gpio_fd[i] != -1) {
            close(gpio_fd[i]);
        }
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int read_temperature(const char *device_path) {
    FILE *file;
    char line[256];
    int temp_celsius;

    file = fopen(device_path, "r");
    if (!file) {
        perror("Failed to open device file");
        return -1;
    }

    while (fgets(line, sizeof(line), file)) {
        if (strstr(line, "t=")) {
            sscanf(line, "t=%d", &temp_celsius);
            break;
        }
    }

    fclose(file);
    return temp_celsius / 1000.0;
}

int main() {
    const char *device_paths[3] = {
        W1_DEVICE_PATH W1_DEVICE_PREFIX "000000000000",
        W1_DEVICE_PATH W1_DEVICE_PREFIX "000000000001",
        W1_DEVICE_PATH W1_DEVICE_PREFIX "000000000002"
    };

    // Initialize libgpiod
    gpiod_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Open GPIO lines
    for (int i = 0; i < 3; i++) {
        gpio_fd[i] = gpiod_chip_get_line(gpiod_chip, i);
        if (gpio_fd[i] == -1) {
            perror("Failed to get GPIO line");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    // Request the line as output
    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_output(gpio_fd[i], "ds18b20", 0) != 0) {
            perror("Failed to request GPIO line as output");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    // Set the GPIO lines high
    for (int i = 0; i < 3; i++) {
        if (gpiod_line_set_value(gpio_fd[i], 1) != 0) {
            perror("Failed to set GPIO line high");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    // Wait for 750 milliseconds
    usleep(750000);

    // Set the GPIO lines low
    for (int i = 0; i < 3; i++) {
        if (gpiod_line_set_value(gpio_fd[i], 0) != 0) {
            perror("Failed to set GPIO line low");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    // Wait for 480 microseconds
    usleep(480000);

    // Read the temperature from the device
    for (int i = 0; i < 3; i++) {
        const char *device_path = device_paths[i];
        int temp_celsius = read_temperature(device_path);
        if (temp_celsius == -1) {
            fprintf(stderr, "Failed to read temperature from device %s\n", device_path);
            continue;
        }

        // Check if the reading is valid
        if (temp_celsius > -40 && temp_celsius < 125) {
            printf("Temperature from device %s: %.2f°C\n", device_path, temp_celsius);
        } else {
            fprintf(stderr, "Invalid temperature reading from device %s\n", device_path);
        }
    }

    // Clean up and exit
    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define HTU21D_I2C_ADDR 0x40
#define HTU21D_READ_TEMP_HOLD 0xE3
#define HTU21D_READ_HUMIDITY_HOLD 0xE5
#define HTU21D_READ_TEMP_NOHOLD 0xF3
#define HTU21D_READ_HUMIDITY_NOHOLD 0xF5
#define HTU21D_RESET 0xFE

#define MAX_RETRIES 3
#define DELAY_SECONDS 60

static int i2c_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int read_htu21d(uint8_t cmd, uint16_t *value) {
    int retries = MAX_RETRIES;
    while (retries--) {
        if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_I2C_ADDR) < 0) {
            perror("Failed to set I2C slave address");
            return -1;
        }

        if (write(i2c_fd, &cmd, 1) != 1) {
            perror("Failed to write command to HTU21D");
            return -1;
        }

        usleep(10000); // Wait for conversion time

        if (read(i2c_fd, value, 2) != 2) {
            perror("Failed to read data from HTU21D");
            return -1;
        }

        // Check CRC
        uint8_t crc = (value[0] >> 8) | (value[1] << 8);
        uint8_t expected_crc = (value[0] ^ value[1]) & 0xFF;
        if (crc != expected_crc) {
            fprintf(stderr, "CRC mismatch, retrying...\n");
            continue;
        }

        return 0;
    }
    fprintf(stderr, "HTU21D read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

int main() {
    // Initialize GPIO
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, 17); // Assuming SDA is connected to GPIO17
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(gpio_line, "htu21d-sda");
    if (ret) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        uint16_t temp_raw, humidity_raw;

        // Read temperature
        if (read_htu21d(HTU21D_READ_TEMP_NOHOLD, &temp_raw) == 0) {
            float temp_celsius = -46.85 + 175.72 * ((float)temp_raw / 65536.0);
            printf("Temperature: %.2f°C\n", temp_celsius);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        // Read humidity
        if (read_htu21d(HTU21D_READ_HUMIDITY_NOHOLD, &humidity_raw) == 0) {
            float humidity_percent = -6.0 + 125.0 * ((float)humidity_raw / 65536.0);
            printf("Humidity: %.2f%%\n", humidity_percent);
        } else {
            fprintf(stderr, "Failed to read humidity\n");
        }

        sleep(DELAY_SECONDS);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
