}

int main() {
    int fd_gpio4, fd_gpio18;
    struct gpiod_chip *chip;
    struct gpiod_line *line4, *line18;
    enum gpiod_line_bulk_direction direction;
    enum gpiod_line_bulk_value value;
    struct timespec sleep_time = {0, 50000000}; // 0.05 seconds

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
