    if (!line4) {
        perror("Failed to get line 4");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("Failed to get line 18");
        gpiod_line_release(line4);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines for output
    if (gpiod_line_request_output(line4, "GPIO4", 0)) {
        perror("Failed to request line 4 as output");
        gpiod_line_release(line4);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
