        gpiod_line_release(line4);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set initial state
    value.values[0] = 0; // GPIO4 low
    value.values[1] = 0; // GPIO18 low
