    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO for IRQ
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    irq_line = gpiod_chip_get_line(gpio_chip, 17); // Assuming IRQ line is GPIO17
    if (!irq_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_input(irq_line, "ADXL345 IRQ");
    if (ret) {
