        // Print the readings
        printf("X: %d, Y: %d, Z: %d\n", data[0], data[1], data[2]);

        // Wait for 0.1 seconds
        usleep(100000);
    }

    // Release resources
    gpiod_line_release(irq_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

