    should_exit = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    uint8_t data[5];
    int i, j;
    float humidity, temperature;

    // Register signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open(DHT_GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines for DHT22
    line = gpiod_chip_get_line(chip, DHT_GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set line direction to output
    ret = gpiod_line_request_output(line, "dht22", 0);
    if (ret) {
        perror("Failed to set line direction");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Send start signal
    gpiod_line_set_value(line, 0); // Low for 18ms
    usleep(18000);
    gpiod_line_set_value(line, 1); // High for 40us
    usleep(40);

    // Read data
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            while (gpiod_line_get_value(line) == 0);
            usleep(28);
            if (gpiod_line_get_value(line) == 1) {
                data[i] |= (1 << (7 - j));
            }
            while (gpiod_line_get_value(line) == 1);
        }
    }

    // Release line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    // Check checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "Checksum error\n");
        return EXIT_FAILURE;
    }

    // Calculate humidity and temperature
    humidity = (data[0] << 8) | data[1];
    temperature = (data[2] << 8) | data[3];

    // Print results
    printf("Humidity: %.2f%%\n", humidity / 10.0);
    printf("Temperature: %.2f°C\n", temperature / 10.0);

    return EXIT_SUCCESS;
}

