    enum gpiod_line_request_flags flags = GPIOD_LINE_REQUEST_FLAG_OUTPUT;
    int ret;

    // Register signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    // Request lines
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        perror("Failed to get line 2");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(line2, "gpio2", 0, flags);
    if (ret) {
        perror("Failed to request line 2 as output");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        perror("Failed to get line 3");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(line3, "gpio3", 0, flags);
    if (ret) {
        perror("Failed to request line 3 as output");
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set initial state
    ret = gpiod_line_set_value(line2, 0);
    if (ret) {
        perror("Failed to set line 2 to low");
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_set_value(line3, 0);
    if (ret) {
        perror("Failed to set line 3 to low");
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        printf("GPIO 2: %d, GPIO 3: %d\n", gpiod_line_get_value(line2), gpiod_line_get_value(line3));
        sleep(1);
    }

    // Release lines and close chip
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

