#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int duty_cycle = 50; // Initial duty cycle percentage
    int period_ms = 2000; // PWM period in milliseconds

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up PWM on GPIO 18 with a period of 2000 ms
    if (gpioSetPWMfrequency(PWM_PIN, period_ms) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set initial duty cycle
    if (gpioSetPWMdutycycle(PWM_PIN, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("PWM output started on GPIO %d with initial duty cycle %d%%\n", PWM_PIN, duty_cycle);

    while (keep_running) {
        // Update duty cycle every 0.02 seconds
        duty_cycle = (duty_cycle + 1) % 101; // Cycle through 0% to 100%
        if (gpioSetPWMdutycycle(PWM_PIN, duty_cycle) < 0) {
            fprintf(stderr, "Failed to update PWM duty cycle\n");
            break;
        }
        usleep(200000); // Sleep for 0.02 seconds
    }

    // Clean up and terminate pigpio library
    gpioTerminate();

    printf("PWM output stopped\n");

    return EXIT_SUCCESS;
}

