#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define DELAY_MS 200

static int gpiod_chip = -1;
static int i2c_fd = -1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
}

void signal_handler(int signum) {
    printf("Interrupt received, cleaning up...\n");
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    const char *chip_name = "gpiochip0";
    const char *line_name = "GPIO23"; // SCL
    const char *line_name2 = "GPIO24"; // SDA

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpiod_chip = gpiod_chip_open(chip_name);
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    struct gpiod_line *scl_line = gpiod_chip_get_line(gpiod_chip, line_name);
    struct gpiod_line *sda_line = gpiod_chip_get_line(gpiod_chip, line_name2);

    if (!scl_line || !sda_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    // Request lines as output
    if (gpiod_line_request_output(scl_line, "tcs34725_scl", 0) ||
        gpiod_line_request_output(sda_line, "tcs34725_sda", 0)) {
        perror("Failed to request GPIO lines as output");
        gpiod_line_release(scl_line);
        gpiod_line_release(sda_line);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    // Set initial state of SCL and SDA
    gpiod_line_set_value(scl_line, 1);
    gpiod_line_set_value(sda_line, 1);

    // Open I2C device
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        gpiod_line_release(scl_line);
        gpiod_line_release(sda_line);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_line_release(scl_line);
        gpiod_line_release(sda_line);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    // Read from TCS34725
    uint8_t command = 0x00; // Start conversion
    if (write(i2c_fd, &command, 1) != 1) {
        perror("Failed to write command to TCS34725");
        close(i2c_fd);
        gpiod_line_release(scl_line);
        gpiod_line_release(sda_line);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    while (1) {
        usleep(DELAY_MS * 1000);

        // Read data from TCS34725
        uint8_t data[4];
        if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
            perror("Failed to read data from TCS34725");
            close(i2c_fd);
            gpiod_line_release(scl_line);
            gpiod_line_release(sda_line);
            gpiod_chip_close(gpiod_chip);
            return EXIT_FAILURE;
        }

        // Print readings
        printf("Red: %d, Green: %d, Blue: %d, Clear: %d\n",
               data[0], data[1], data[2], data[3]);
    }

    // Cleanup on exit
    cleanup();

    return EXIT_SUCCESS;
}

