#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <libv4l2.h>

#define DEVICE "/dev/video0"
#define OUTPUT_FILE "captured_image.jpg"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *buffer;
    int ret;

    // Open the video device
    fd = open(DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open video device");
        return EXIT_FAILURE;
    }

    // Query the capabilities of the device
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret == -1) {
        perror("Failed to query device capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    // Check if the device supports video capture
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set the format to YUYV 640x480
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret == -1) {
        perror("Failed to set format");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret == -1) {
        perror("Failed to request buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffers
    buffer = mmap(NULL, req.count * fmt.fmt.pix.sizeimage, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Failed to map buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    // Queue the buffers
    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.index = i;
        buf.m.mem_offset = buffer[i] * fmt.fmt.pix.sizeimage;

        ret = ioctl(fd, VIDIOC_QBUF, &buf);
        if (ret == -1) {
            perror("Failed to queue buffer");
            munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ret = ioctl(fd, VIDIOC_STREAMON, &type);
    if (ret == -1) {
        perror("Failed to start streaming");
        munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
        close(fd);
        return EXIT_FAILURE;
    }

    // Wait for a frame
    while (1) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        struct timeval tv;
        tv.tv_sec = 5;
        tv.tv_usec = 0;

        ret = select(fd + 1, &fds, NULL, NULL, &tv);
        if (ret == -1) {
            perror("Select failed");
            munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
            close(fd);
            return EXIT_FAILURE;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout waiting for frame\n");
            munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
            close(fd);
            return EXIT_FAILURE;
        }

        // Dequeue the buffer
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        ret = ioctl(fd, VIDIOC_DQBUF, &buf);
        if (ret == -1) {
            perror("Failed to dequeue buffer");
            munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
            close(fd);
            return EXIT_FAILURE;
        }

        // Save the frame to a file
        FILE *file = fopen(OUTPUT_FILE, "wb");
        if (file == NULL) {
            perror("Failed to open output file");
            munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
            close(fd);
            return EXIT_FAILURE;
        }

        fwrite(buffer + buf.m.offset, 1, buf.bytesused, file);
        fclose(file);

        // Queue the buffer again
        ret = ioctl(fd, VIDIOC_QBUF, &buf);
        if (ret == -1) {
            perror("Failed to queue buffer");
            munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Stop streaming
    ret = ioctl(fd, VIDIOC_STREAMOFF, &type);
    if (ret == -1) {
        perror("Failed to stop streaming");
        munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
        close(fd);
        return EXIT_FAILURE;
    }

    // Unmap the buffers
    munmap(buffer, req.count * fmt.fmt.pix.sizeimage);

    // Close the video device
    close(fd);

    return EXIT_SUCCESS;
}

