#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SSD1306_ADDRESS 0x3C
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64

#define SCREEN_BUFFER_SIZE (SSD1306_WIDTH * SSD1306_HEIGHT / 8)

static int gpiod_chip = -1;
static int i2c_fd = -1;

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpiod_chip >= 0) {
        gpiod_chip_close(gpiod_chip);
    }
}

void signal_handler(int signum) {
    printf("Signal %d received, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    // Register signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    // Initialize GPIO chip
    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_ADDRESS) == -1) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize SSD1306
    unsigned char init_sequence[] = {
        0xAE, // Display off
        0xD5, 0xF0, // Set contrast
        0xA8, 0x3F, // Set multiplex ratio
        0xD3, 0x00, // Set display offset
        0x40, // Set start line
        0x8D, 0x14, // Set charge pump
        0xA1, // Set segment remap
        0xC8, // Set com scan direction
        0xDA, 0x12, // Set com pins configuration
        0x81, 0xCF, // Set precharge period
        0xD9, 0xF1, // Set vcomh
        0xDB, 0x20, // Set display bias
        0xA4, // Entire display on
        0xA6, // Normal display
        0xAF  // Display on
    };

    for (size_t i = 0; i < sizeof(init_sequence); ++i) {
        if (write(i2c_fd, &init_sequence[i], 1) != 1) {
            perror("Failed to write initialization sequence");
            cleanup();
            return EXIT_FAILURE;
        }
        usleep(1000); // Wait for 1 ms between commands
    }

    // Allocate screen buffer
    unsigned char screen_buffer[SCREEN_BUFFER_SIZE];
    memset(screen_buffer, 0, SCREEN_BUFFER_SIZE);

    // Main loop
    while (1) {
        // Example: Display a message
        const char message[] = "Hello, SSD1306!";
        size_t message_length = strlen(message);
        size_t row = 0;
        size_t col = 0;

        for (size_t i = 0; i < message_length; ++i) {
            screen_buffer[row * SSD1306_WIDTH + col] |= (1 << (7 - (col % 8)));
            col++;
            if (col == SSD1306_WIDTH) {
                col = 0;
                row++;
            }
        }

        // Send buffer to display
        if (write(i2c_fd, screen_buffer, SCREEN_BUFFER_SIZE) != SCREEN_BUFFER_SIZE) {
            perror("Failed to send screen buffer");
            cleanup();
            return EXIT_FAILURE;
        }

        // Wait for 0.1 seconds
        usleep(100000);
    }

    // Cleanup on exit
    cleanup();
    return EXIT_SUCCESS;
}

