#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_8 8
#define PWM_PIN_9 9
#define PWM_PIN_11 11
#define PWM_PIN_18 18

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    // Set up PWM pins
    if (gpioSetMode(PWM_PIN_8, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", PWM_PIN_8);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_9, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", PWM_PIN_9);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_11, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", PWM_PIN_11);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", PWM_PIN_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set PWM frequency to 50 Hz
    if (gpioSetPWMfrequency(PWM_PIN_8, 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_PIN_8);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_9, 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_PIN_9);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_11, 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_PIN_11);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_18, 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_PIN_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set initial duty cycle to 0%
    if (gpioPWM(PWM_PIN_8, 0) < 0) {
        fprintf(stderr, "Failed to set duty cycle for GPIO %d\n", PWM_PIN_8);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN_9, 0) < 0) {
        fprintf(stderr, "Failed to set duty cycle for GPIO %d\n", PWM_PIN_9);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN_11, 0) < 0) {
        fprintf(stderr, "Failed to set duty cycle for GPIO %d\n", PWM_PIN_11);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN_18, 0) < 0) {
        fprintf(stderr, "Failed to set duty cycle for GPIO %d\n", PWM_PIN_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    while (keep_running) {
        // Toggle duty cycle between 0% and 100%
        for (int duty = 0; duty <= 100; duty += 10) {
            printf("Duty Cycle: %d%%\n", duty);
            gpioPWM(PWM_PIN_8, duty);
            gpioPWM(PWM_PIN_9, duty);
            gpioPWM(PWM_PIN_11, duty);
            gpioPWM(PWM_PIN_18, duty);
            usleep(500000); // Sleep for 0.5 seconds
        }
        for (int duty = 100; duty >= 0; duty -= 10) {
            printf("Duty Cycle: %d%%\n", duty);
            gpioPWM(PWM_PIN_8, duty);
            gpioPWM(PWM_PIN_9, duty);
            gpioPWM(PWM_PIN_11, duty);
            gpioPWM(PWM_PIN_18, duty);
            usleep(500000); // Sleep for 0.5 seconds
        }
    }

    // Clean up
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 23
#define BAUD_RATE 9600

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int fd_trigger, fd_echo;
    struct gpiod_chip *chip;
    struct gpiod_line *line_trigger, *line_echo;
    struct timespec start, end;
    long duration;
    double distance;
    char buffer[256];

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Open the chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the lines
    line_trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    line_echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!line_trigger || !line_echo) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the lines for output and input
    if (gpiod_line_request_output(line_trigger, "trigger", 0) < 0 ||
        gpiod_line_request_input(line_echo, "echo", 0) < 0) {
        perror("Failed to request GPIO lines");
        gpiod_line_release(line_trigger);
        gpiod_line_release(line_echo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the serial port for debugging output
    fd_trigger = open("/dev/ttyUSB0", O_WRONLY | O_NOCTTY | O_NDELAY);
    if (fd_trigger < 0) {
        perror("Failed to open trigger serial port");
        gpiod_line_release(line_trigger);
        gpiod_line_release(line_echo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        // Send a pulse to trigger the sensor
        gpiod_line_set_value(line_trigger, 1);
        usleep(10);
        gpiod_line_set_value(line_trigger, 0);

        // Wait for the echo pin to go high
        while (gpiod_line_get_value(line_echo) == 0) {
            if (should_exit) {
                break;
            }
        }

        // Record the start time
        clock_gettime(CLOCK_MONOTONIC, &start);

        // Wait for the echo pin to go low
        while (gpiod_line_get_value(line_echo) == 1) {
            if (should_exit) {
                break;
            }
        }

        // Record the end time
        clock_gettime(CLOCK_MONOTONIC, &end);

        // Calculate the duration of the pulse
        duration = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);
        duration /= 1000000; // Convert to microseconds

        // Calculate the distance in centimeters
        distance = duration / 58.2;

        // Print the distance
        snprintf(buffer, sizeof(buffer), "Distance: %.2f cm\n", distance);
        write(fd_trigger, buffer, strlen(buffer));

        // Sleep for 0.2 seconds
        sleep(0.2);
    }

    // Clean up
    close(fd_trigger);
    gpiod_line_release(line_trigger);
    gpiod_line_release(line_echo);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 18

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int result;

    // Initialize pigpio library
    result = gpioInitialise();
    if (result < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioErrDescription(result));
        return EXIT_FAILURE;
    }

    // Set up the LED pin as an output
    result = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (result < 0) {
        fprintf(stderr, "Failed to set mode for LED pin: %s\n", gpioErrDescription(result));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    while (keep_running) {
        // Set the LED pin high to turn it on
        result = gpioWrite(LED_PIN, 1);
        if (result < 0) {
            fprintf(stderr, "Failed to write to LED pin: %s\n", gpioErrDescription(result));
            break;
        }

        // Wait for 0.01 seconds
        usleep(100000);

        // Set the LED pin low to turn it off
        result = gpioWrite(LED_PIN, 0);
        if (result < 0) {
            fprintf(stderr, "Failed to write to LED pin: %s\n", gpioErrDescription(result));
            break;
        }

        // Wait for 0.01 seconds
        usleep(100000);
    }

    // Clean up and terminate pigpio
    gpioTerminate();

    return EXIT_SUCCESS;
}

