#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <libv4l2.h>

#define DEVICE "/dev/video0"
#define BUFFER_SIZE 2048 * 1024
#define FILE_NAME "captured_image.jpg"

static void usage(const char *progname) {
    fprintf(stderr, "Usage: %s\n", progname);
    exit(EXIT_FAILURE);
}

static void error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

static void close_device(int fd) {
    if (close(fd) == -1) {
        error("Failed to close device");
    }
}

static void release_resources(int fd) {
    close_device(fd);
}

static int open_device(const char *device) {
    int fd = open(device, O_RDWR | O_NONBLOCK);
    if (fd == -1) {
        error("Failed to open device");
    }
    return fd;
}

static int init_device(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        error("Failed to query capabilities");
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        error("Device does not support video capture");
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        error("Failed to set format");
    }

    return 0;
}

static int prepare_buffers(int fd) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        error("Failed to request buffers");
    }

    struct v4l2_buffer buf;
    for (int i = 0; i < req.count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            error("Failed to query buffer");
        }

        void *data = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (data == MAP_FAILED) {
            error("Failed to map buffer");
        }

        buf.m.data = data;
        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            error("Failed to queue buffer");
        }
    }

    return 0;
}

static int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        error("Failed to start streaming");
    }

    return 0;
}

static int capture_image(int fd) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        error("Failed to dequeue buffer");
    }

    FILE *file = fopen(FILE_NAME, "wb");
    if (!file) {
        error("Failed to open file");
    }

    fwrite(buf.m.data, 1, buf.bytesused, file);
    fclose(file);

    munmap(buf.m.data, buf.length);
    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        error("Failed to queue buffer");
    }

    return 0;
}

static void stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        error("Failed to stop streaming");
    }
}

static void signal_handler(int signum) {
    printf("Signal received, stopping...\n");
    stop_streaming(fd);
    release_resources(fd);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    if (argc != 1) {
        usage(argv[0]);
    }

    signal(SIGINT, signal_handler);

    int fd = open_device(DEVICE);
    if (init_device(fd) == -1) {
        release_resources(fd);
        exit(EXIT_FAILURE);
    }

    if (prepare_buffers(fd) == -1) {
        release_resources(fd);
        exit(EXIT_FAILURE);
    }

    if (start_streaming(fd) == -1) {
        release_resources(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        capture_image(fd);
        usleep(50000); // Sleep for 0.05 seconds
    }

