void display_init(void) {
    // Configure LCD pins
    int data_pins[] = {23, 24, 25, 8, 7, 6, 5, 4}; // Data lines
    int control_pins[] = {22, 21, 18}; // Control lines (RS, RW, E)

    struct gpiod_line_bulk_request req;
    memset(&req, 0, sizeof(req));
    req.consumer = "lcd";

    for (int i = 0; i < 8; i++) {
        req.lines[i] = gpiod_chip_get_line(gpiod_ctx, data_pins[i]);
        if (gpiod_line_request_output(req.lines[i], &req.consumer, 0) != 0) {
            perror("Failed to request data line");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 3; i++) {
        req.lines[8 + i] = gpiod_chip_get_line(gpiod_ctx, control_pins[i]);
        if (gpiod_line_request_output(req.lines[8 + i], &req.consumer, 0) != 0) {
            perror("Failed to request control line");
            exit(EXIT_FAILURE);
        }
    }

    // Initialize LCD
    send_command(0x38); // Function set: 8-bit mode, 2 lines, 5x8 font
    send_command(0x0C); // Display on, cursor off, blink off
    send_command(0x01); // Clear display
    send_command(0x06); // Entry mode set: increment, no shift
}

