#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <paho-mqtt-c/paho-mqttc.h>

// Define GPIO pin for sensor
#define SENSOR_PIN 17

// MQTT broker details
const char* broker = "mqtt.example.com";
const int port = 1883;
const char* client_id = "sensor_publisher";
const char* topic = "sensor/reading";

// Global variables
MQTTClient client;
MQTTClient_connectOptions conn_opts;
MQTTClient_message pubmsg;
MQTTClient_deliveryToken token;

// Signal handler
void signal_handler(int sig) {
    printf("Received signal %d\n", sig);
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    exit(0);
}

// Sensor validation function
int validate_sensor_reading(float reading) {
    // Example validation: check if reading is within a valid range
    if (reading >= 0 && reading <= 100) {
        return 1;
    }
    return 0;
}

// Callback for connection lost
void on_connection_lost(void *context, char *cause) {
    printf("Connection lost: %s\n", cause);
    MQTTClient_connect(client, &conn_opts);
}

// Callback for publish completion
void on_publish_complete(void *context, MQTTClient_deliveryToken dt) {
    printf("Message with token %d delivered\n", dt);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO pin as input
    if (gpioSetMode(SENSOR_PIN, PI_INPUT)) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Initialize MQTT client
    client = MQTTClient_create(NULL, client_id, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (client == NULL) {
        fprintf(stderr, "Failed to create MQTT client\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up MQTT connection options
    conn_opts.keepAliveInterval = 60;
    conn_opts.cleansession = 1;
    conn_opts.username = "your_username";
    conn_opts.password = "your_password";
    conn_opts.onSuccess = NULL;
    conn_opts.onFailure = NULL;
    conn_opts.onConnect = NULL;
    conn_opts.onDisconnect = on_connection_lost;
    conn_opts.onSubscribe = NULL;
    conn_opts.onUnsubscribe = NULL;
    conn_opts.onMessageArrived = NULL;

    // Connect to MQTT broker
    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        MQTTClient_destroy(&client);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Subscribe to topic
    if (MQTTClient_subscribe(client, topic, 0) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to subscribe to topic\n");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read sensor data
        float reading = 0.0;
        if (gpioRead(SENSOR_PIN) == 1) {
            reading = 100.0; // Example reading
        } else {
            reading = 0.0;
        }

        // Validate sensor reading
        if (validate_sensor_reading(reading)) {
            // Prepare message
            pubmsg.payload = (char*)&reading;
            pubmsg.payloadlen = sizeof(reading);
            pubmsg.qos = 1;
            pubmsg.retained = 0;

            // Publish message
            if (MQTTClient_publish(client, topic, &pubmsg, &token) != MQTTCLIENT_SUCCESS) {
                fprintf(stderr, "Failed to publish message\n");
            } else {
                printf("Published reading: %.2f\n", reading);
            }
        } else {
            printf("Invalid reading: %.2f\n", reading);
        }

        // Sleep for 0.01 seconds
        usleep(100000);
    }

    // Disconnect from MQTT broker
    MQTTClient_disconnect(client, 1000);

    // Destroy MQTT client
    MQTTClient_destroy(&client);

    // Terminate GPIO
    gpioTerminate();

    return 0;
}

