#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 22
#define MAX_TIMEOUT 1000000 // 1 second in microseconds

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int fd_trigger, fd_echo;
    struct gpiod_chip *chip;
    struct gpiod_line *line_trigger, *line_echo;
    uint32_t value;
    struct timespec start, end;
    long duration;
    double distance;

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    line_trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!line_trigger) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line_echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!line_echo) {
        perror("Failed to get echo line");
        gpiod_line_release(line_trigger);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines as outputs and inputs respectively
    if (gpiod_line_request_output(line_trigger, "trigger", 0) < 0) {
        perror("Failed to request trigger line as output");
        gpiod_line_release(line_trigger);
        gpiod_line_release(line_echo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line_echo, "echo") < 0) {
        perror("Failed to request echo line as input");
        gpiod_line_release(line_trigger);
        gpiod_line_release(line_echo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (!should_exit) {
        // Send a pulse to the trigger pin
        gpiod_line_set_value(line_trigger, 1);
        usleep(10); // Wait for 10 microseconds
        gpiod_line_set_value(line_trigger, 0);

        // Wait for the echo pin to go high
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line_echo) == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
                perror("Failed to get current time");
                break;
            }
            duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            if (duration > MAX_TIMEOUT) {
                printf("Echo did not respond\n");
                break;
            }
        }

        // Wait for the echo pin to go low
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line_echo) == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
                perror("Failed to get current time");
                break;
            }
            duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            if (duration > MAX_TIMEOUT) {
                printf("Echo did not respond\n");
                break;
            }
        }

        // Calculate distance
        if (duration > 0) {
            distance = duration * 0.0343 / 2; // Speed of sound is approximately 343 m/s
            printf("Distance: %.2fm\n", distance);
        } else {
            printf("Invalid reading\n");
        }

        // Sleep for 0.1 seconds
        sleep(1);
    }

    // Release resources
    gpiod_line_release(line_trigger);
    gpiod_line_release(line_echo);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

