#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <mqtt.h>

#define GPIO_PIN 17
#define MQTT_BROKER "mqtt.example.com"
#define MQTT_TOPIC "sensor/data"
#define MQTT_USER "username"
#define MQTT_PASSWORD "password"

static int gpiod_fd = -1;
static struct gpiochip_info chip_info;
static struct gpiod_line *line;
static struct mqtt_client *client;
static bool running = true;

void signal_handler(int signum) {
    running = false;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    gpiod_fd = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_fd == -1) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    if (gpiod_chip_get_info(gpiod_fd, &chip_info) != 0) {
        perror("Failed to get GPIO chip info");
        close(gpiod_fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(gpiod_fd, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        close(gpiod_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "sensor") != 0) {
        perror("Failed to request GPIO line input");
        gpiod_line_release(line);
        close(gpiod_fd);
        return EXIT_FAILURE;
    }

    // Initialize MQTT
    client = mqtt_client_new(MQTT_BROKER, MQTT_USER, MQTT_PASSWORD);
    if (!client) {
        perror("Failed to create MQTT client");
        gpiod_line_release(line);
        close(gpiod_fd);
        return EXIT_FAILURE;
    }

    if (mqtt_client_connect(client) != MQTT_CLIENT_SUCCESS) {
        perror("Failed to connect to MQTT broker");
        mqtt_client_destroy(client);
        gpiod_line_release(line);
        close(gpiod_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int value = gpiod_line_get_value(line);
        if (value == -1) {
            perror("Failed to read GPIO line value");
            break;
        }

        char buffer[256];
        snprintf(buffer, sizeof(buffer), "%d", value);

        if (mqtt_client_publish(client, MQTT_TOPIC, buffer, strlen(buffer)) != MQTT_CLIENT_SUCCESS) {
            perror("Failed to publish MQTT message");
            break;
        }

        sleep(1); // Wait for 1 second before publishing again
    }

    // Clean up
    mqtt_client_disconnect(client);
    mqtt_client_destroy(client);
    gpiod_line_release(line);
    close(gpiod_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_DUTYCYCLE 50

static volatile sig_atomic_t quit = 0;

void signal_handler(int signum) {
    quit = 1;
}

int main() {
    int result;

    // Initialize pigpio library
    result = gpioInitialise();
    if (result < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioErrDescription(result));
        return EXIT_FAILURE;
    }

    // Set up PWM on GPIO 18
    result = gpioSetMode(PWM_PIN, PI_OUTPUT);
    if (result < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d: %s\n", PWM_PIN, gpioErrDescription(result));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    result = gpioPWM(PWM_PIN, PWM_FREQ, PWM_DUTYCYCLE);
    if (result < 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d: %s\n", PWM_PIN, gpioErrDescription(result));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    while (!quit) {
        printf("PWM duty cycle: %d%%\n", PWM_DUTYCYCLE);
        sleep(5);
    }

    // Clean up and terminate pigpio
    gpioPWM(PWM_PIN, 0, 0); // Turn off PWM
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
