#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define TIMEOUT_MS 5000 // Timeout for the echo signal in milliseconds

static volatile sig_atomic_t should_exit = 0;

void handle_interrupt(int signum) {
    should_exit = 1;
}

int main() {
    int fd_trigger, fd_echo;
    struct gpiod_chip *chip;
    struct gpiod_line *line_trigger, *line_echo;
    struct timespec start_time, end_time;
    long duration_us;
    double distance_cm;
    int ret;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_interrupt);

    // Open the chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    // Get the lines
    line_trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    line_echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!line_trigger || !line_echo) {
        perror("Failed to get line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the lines for output and input
    ret = gpiod_line_request_output(line_trigger, "trigger", 0);
    if (ret) {
        perror("Failed to request trigger line");
        gpiod_line_release(line_trigger);
        gpiod_line_release(line_echo);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(line_echo, "echo");
    if (ret) {
        perror("Failed to request echo line");
        gpiod_line_release(line_trigger);
        gpiod_line_release(line_echo);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        // Send a pulse to the trigger pin
        gpiod_line_set_value(line_trigger, 1);
        usleep(10); // Wait for 10 microseconds
        gpiod_line_set_value(line_trigger, 0);

        // Wait for the echo signal to return
        ret = clock_gettime(CLOCK_MONOTONIC, &start_time);
        if (ret) {
            perror("Failed to get current time");
            gpiod_line_release(line_trigger);
            gpiod_line_release(line_echo);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        while (gpiod_line_get_value(line_echo) == 0) {
            ret = clock_gettime(CLOCK_MONOTONIC, &end_time);
            if (ret) {
                perror("Failed to get current time");
                gpiod_line_release(line_trigger);
                gpiod_line_release(line_echo);
                gpiod_chip_close(chip);
                exit(EXIT_FAILURE);
            }

            duration_us = (end_time.tv_sec - start_time.tv_sec) * 1000000 +
                           (end_time.tv_nsec - start_time.tv_nsec) / 1000;

            if (duration_us > TIMEOUT_MS * 1000) {
                printf("No response from sensor\n");
                break;
            }
        }

        if (gpiod_line_get_value(line_echo) == 1) {
            ret = clock_gettime(CLOCK_MONOTONIC, &end_time);
            if (ret) {
                perror("Failed to get current time");
                gpiod_line_release(line_trigger);
                gpiod_line_release(line_echo);
                gpiod_chip_close(chip);
                exit(EXIT_FAILURE);
            }

            duration_us = (end_time.tv_sec - start_time.tv_sec) * 1000000 +
                           (end_time.tv_nsec - start_time.tv_nsec) / 1000;

            // Calculate distance in centimeters
            distance_cm = duration_us / 58.2;

            printf("Distance: %.2f cm\n", distance_cm);
        }

        usleep(200000); // Wait for 0.2 seconds
    }

    // Release the lines
    gpiod_line_release(line_trigger);
    gpiod_line_release(line_echo);

    // Close the chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_FREQ 5000 // Frequency in Hz
#define PWM_DUTY_CYCLE 50 // Duty cycle in percentage

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    // Set up PWM on GPIOs 17, 18, 22, 23
    if (gpioSetPWMfrequency(17, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO 17\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(18, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO 18\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(22, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO 22\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(23, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO 23\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(17, 1024) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO 17\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(18, 1024) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO 18\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(22, 1024) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO 22\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(23, 1024) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO 23\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set initial duty cycle
    if (gpioPWM(17, PWM_DUTY_CYCLE * 1024 / 100) < 0) {
        fprintf(stderr, "Failed to set initial duty cycle on GPIO 17\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(18, PWM_DUTY_CYCLE * 1024 / 100) < 0) {
        fprintf(stderr, "Failed to set initial duty cycle on GPIO 18\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(22, PWM_DUTY_CYCLE * 1024 / 100) < 0) {
        fprintf(stderr, "Failed to set initial duty cycle on GPIO 22\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(23, PWM_DUTY_CYCLE * 1024 / 100) < 0) {
        fprintf(stderr, "Failed to set initial duty cycle on GPIO 23\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    while (running) {
        printf("Duty cycle: %d%%\n", PWM_DUTY_CYCLE);
        fflush(stdout);
        usleep(100000); // Sleep for 0.1 seconds
    }

    // Clean up
    gpioPWM(17, 0);
    gpioPWM(18, 0);
    gpioPWM(22, 0);
    gpioPWM(23, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <paho-mqtt-c/paho-mqttc.h>

// Define GPIO pin for sensor
#define SENSOR_PIN 18

// MQTT broker details
const char* broker = "mqtt.example.com";
const int port = 1883;
const char* client_id = "sensor_publisher";
const char* topic = "sensor/data";

// Global variables
MQTTClient client;
MQTTClient_connectOptions conn_opts;
MQTTClient_message pubmsg;
MQTTClient_deliveryToken token;

void on_connect(void *context, MQTTClient_deliveryToken dt) {
    printf("Connected with token %d\n", dt);
}

void on_publish(void *context, MQTTClient_deliveryToken dt) {
    printf("Publish completed with token %d\n", dt);
}

void on_error(void *context, int rc) {
    printf("Error: %d\n", rc);
}

void on_disconnect(void *context, MQTTClient_deliveryToken dt) {
    printf("Disconnected with token %d\n", dt);
}

void on_messageArrived(void *context, MQTTClient_message *message) {
    printf("Message arrived: %.*s\n", message->payloadlen, message->payload);
    MQTTClient_freeMessage(&message);
}

void signal_handler(int sig) {
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up MQTT client
    client = MQTTClient_create(NULL, client_id, NULL, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (client == NULL) {
        fprintf(stderr, "Failed to create MQTT client\n");
        gpioTerminate();
        return 1;
    }

    conn_opts.keepAliveInterval = 60;
    conn_opts.cleansession = 1;
    conn_opts.username = "your_username";
    conn_opts.password = "your_password";

    if (MQTTClient_connect(client, broker, port, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    // Subscribe to topic
    if (MQTTClient_subscribe(client, topic, 0) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to subscribe to topic\n");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    // Register callbacks
    MQTTClient_setCallbacks(client, NULL, on_connect, on_publish, on_error, on_disconnect);

    // Signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read sensor data
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value == -1) {
            fprintf(stderr, "Failed to read sensor value\n");
            continue;
        }

        // Validate sensor data
        if (sensor_value < 0 || sensor_value > 1023) {
            fprintf(stderr, "Invalid sensor value: %d\n", sensor_value);
            continue;
        }

        // Create MQTT message
        pubmsg.payload = (char*)&sensor_value;
        pubmsg.payloadlen = sizeof(sensor_value);
        pubmsg.qos = 1;
        pubmsg.retained = 0;

        // Publish message
        if (MQTTClient_publish(client, topic, pubmsg.payloadlen, pubmsg.payload, pubmsg.qos, pubmsg.retained, &token) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish message\n");
            continue;
        }

        // Wait for publish completion
        MQTTClient_waitForCompletion(client, token, 1000);
    }

    // Disconnect and clean up
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return 0;
}

