#include <signal.h>
#include <libgpiod.h>

#define GPIO_17 17
#define GPIO_18 18
#define DELAY 50000 // 50 ms

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    const char *chip_name = "gpiochip0";
    struct gpiod_chip *chip;
    struct gpiod_line *line17, *line18;
    int ret;

    // Register signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get lines 17 and 18
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("Failed to get line 17");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("Failed to get line 18");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request both lines as outputs
    ret = gpiod_line_request_output(line17, "output17", 0);
    if (ret) {
        perror("Failed to request line 17 as output");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line18, "output18", 0);
    if (ret) {
        perror("Failed to request line 18 as output");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        // Toggle line 17
        ret = gpiod_line_set_value(line17, !gpiod_line_get_value(line17));
        if (ret) {
            perror("Failed to set line 17 value");
            break;
        }

        // Toggle line 18
        ret = gpiod_line_set_value(line18, !gpiod_line_get_value(line18));
        if (ret) {
            perror("Failed to set line 18 value");
            break;
        }

        // Report current state
        printf("Line 17: %s, Line 18: %s\n",
               gpiod_line_get_value(line17) ? "High" : "Low",
               gpiod_line_get_value(line18) ? "High" : "Low");

        // Sleep for 50 ms
        usleep(DELAY);
    }

    // Release lines and close chip
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

