#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>

#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE B9600

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int fd;
    struct termios options;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open UART device
    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Failed to open UART device");
        return EXIT_FAILURE;
    }

    // Set up UART options
    if (tcgetattr(fd, &options) != 0) {
        perror("Failed to get UART options");
        close(fd);
        return EXIT_FAILURE;
    }

    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);

    options.c_cflag &= ~PARENB; // No parity
    options.c_cflag &= ~CSTOPB; // One stop bit
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8; // 8 data bits

    options.c_cflag |= CREAD | CLOCAL; // Enable receiver, ignore modem control lines

    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // Disable canonical mode, echo, echoE, and signal chars

    options.c_oflag &= ~OPOST; // Disable output processing

    if (tcsetattr(fd, TCSANOW, &options) != 0) {
        perror("Failed to set UART options");
        close(fd);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        char buffer[256];
        ssize_t bytes_read;

        bytes_read = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s\n", buffer);
        } else if (bytes_read == 0) {
            printf("No data received.\n");
        } else {
            perror("Failed to read from UART");
        }
    }

    // Close UART device
    close(fd);

    return EXIT_SUCCESS;
}

