#define MPU6050_ACCEL_ZOUT_H 0x3F
#define MPU6050_ACCEL_ZOUT_L 0x40
#define MPU6050_TEMP_OUT_H 0x41
#define MPU6050_TEMP_OUT_L 0x42
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_XOUT_L 0x44
#define MPU6050_GYRO_YOUT_H 0x45
#define MPU6050_GYRO_YOUT_L 0x46
#define MPU6050_GYRO_ZOUT_H 0x47
#define MPU6050_GYRO_ZOUT_L 0x48

static int i2c_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *irq_line;

void signal_handler(int signum) {
    printf("Interrupt received, exiting...\n");
    close(i2c_fd);
    gpiod_line_release(irq_line);
    gpiod_chip_close(gpio_chip);
    exit(EXIT_SUCCESS);
}

int main() {
    const char *i2c_dev = "/dev/i2c-1";
    const char *gpio_irq = "gpio17"; // Example GPIO line for interrupt
    int irq_gpio = atoi(gpio_irq);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set up GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request IRQ line
    irq_line = gpiod_chip_get_line(gpio_chip, irq_gpio);
    if (!irq_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request IRQ event
    if (gpiod_line_request_edge_event(irq_line, "mpu6050", GPIOD_EDGE_RISING)) {
        perror("Failed to request IRQ event");
        gpiod_line_release(irq_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        gpiod_line_release(irq_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t accel_x_high, accel_x_low, accel_y_high, accel_y_low, accel_z_high, accel_z_low;
        uint8_t temp_high, temp_low;
        uint8_t gyro_x_high, gyro_x_low, gyro_y_high, gyro_y_low, gyro_z_high, gyro_z_low;

        // Read accelerometer data
        if (read(i2c_fd, &accel_x_high, 1) != 1 || read(i2c_fd, &accel_x_low, 1) != 1 ||
            read(i2c_fd, &accel_y_high, 1) != 1 || read(i2c_fd, &accel_y_low, 1) != 1 ||
            read(i2c_fd, &accel_z_high, 1) != 1 || read(i2c_fd, &accel_z_low, 1) != 1) {
            perror("Failed to read accelerometer data");
            continue;
        }

        // Read temperature data
        if (read(i2c_fd, &temp_high, 1) != 1 || read(i2c_fd, &temp_low, 1) != 1) {
            perror("Failed to read temperature data");
            continue;
        }

        // Read gyroscope data
        if (read(i2c_fd, &gyro_x_high, 1) != 1 || read(i2c_fd, &gyro_x_low, 1) != 1 ||
            read(i2c_fd, &gyro_y_high, 1) != 1 || read(i2c_fd, &gyro_y_low, 1) != 1 ||
            read(i2c_fd, &gyro_z_high, 1) != 1 || read(i2c_fd, &gyro_z_low, 1) != 1) {
            perror("Failed to read gyroscope data");
            continue;
        }

        // Calculate raw values
        int16_t accel_x = (accel_x_high << 8) | accel_x_low;
        int16_t accel_y = (accel_y_high << 8) | accel_y_low;
        int16_t accel_z = (accel_z_high << 8) | accel_z_low;
        int16_t temp = (temp_high << 8) | temp_low;
        int16_t gyro_x = (gyro_x_high << 8) | gyro_x_low;
        int16_t gyro_y = (gyro_y_high << 8) | gyro_y_low;
        int16_t gyro_z = (gyro_z_high << 8) | gyro_z_low;

        // Print readings
        printf("Accel X: %d, Y: %d, Z: %d\n", accel_x, accel_y, accel_z);
        printf("Temp: %d\n", temp);
        printf("Gyro X: %d, Y: %d, Z: %d\n", gyro_x, gyro_y, gyro_z);

        // Sleep for 0.1 seconds
        usleep(100000);
    }

    // Release resources
    gpiod_line_release(irq_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_ID 0xD0
#define BMP280_REG_STATUS 0xF3
#define BMP280_REG_PRESSURE_MSB 0xF7
#define BMP280_REG_PRESSURE_LSB 0xF8
#define BMP280_REG_PRESSURE_XLSB 0xF9
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC

#define BMP280_SOFT_RESET 0xE0
#define BMP280_OSR_P1 0x01
#define BMP280_OSR_P2 0x02
#define BMP280_OSR_P3 0x04
#define BMP280_OSR_T1 0x08
#define BMP280_OSR_T2 0x10
#define BMP280_OSR_T3 0x20
#define BMP280_MODE_SLEEP 0x00
#define BMP280_MODE_FORCED 0x01
#define BMP280_MODE_NORMAL 0x03

static int gpiod_chip = -1;
static int i2c_fd = -1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    const char *i2c_dev_path = "/dev/i2c-1"; // Adjust based on your Raspberry Pi model
    const char *gpio_chip_path = "/dev/gpiochip0"; // Adjust based on your Raspberry Pi model

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    gpiod_chip = gpiod_chip_open(gpio_chip_path);
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open I2C device
    i2c_fd = open(i2c_dev_path, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        gpiod_chip_close(gpiod_chip);
        cleanup();
        return EXIT_FAILURE;
    }

    // Soft reset the BMP280
    uint8_t soft_reset_cmd[] = {BMP280_SOFT_RESET};
    if (write(i2c_fd, soft_reset_cmd, sizeof(soft_reset_cmd)) != sizeof(soft_reset_cmd)) {
        perror("Failed to send soft reset command");
        close(i2c_fd);
        gpiod_chip_close(gpiod_chip);
        cleanup();
        return EXIT_FAILURE;
    }

    // Wait for the device to be ready
    usleep(1000000); // 1 second

    // Set configuration registers
    uint8_t config_reg = BMP280_OSR_P1 | BMP280_OSR_T1 | BMP280_MODE_NORMAL;
    if (write(i2c_fd, &config_reg, 1) != 1) {
        perror("Failed to set configuration register");
        close(i2c_fd);
        gpiod_chip_close(gpiod_chip);
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        // Read the status register to check if data is available
        uint8_t status_reg;
        if (read(i2c_fd, &status_reg, 1) != 1) {
            perror("Failed to read status register");
            continue;
        }

        if ((status_reg & 0x08) == 0) {
            printf("No new data available\n");
            sleep(1);
            continue;
        }

        // Read pressure and temperature data
        uint8_t pressure_msb, pressure_lsb, pressure_xlsb;
        uint8_t temp_msb, temp_lsb, temp_xlsb;

        if (read(i2c_fd, &pressure_msb, 1) != 1) {
            perror("Failed to read pressure MSB");
            continue;
        }
        if (read(i2c_fd, &pressure_lsb, 1) != 1) {
            perror("Failed to read pressure LSB");
            continue;
        }
        if (read(i2c_fd, &pressure_xlsb, 1) != 1) {
            perror("Failed to read pressure XLSB");
            continue;
        }
        if (read(i2c_fd, &temp_msb, 1) != 1) {
            perror("Failed to read temperature MSB");
            continue;
        }
        if (read(i2c_fd, &temp_lsb, 1) != 1) {
            perror("Failed to read temperature LSB");
            continue;
        }
        if (read(i2c_fd, &temp_xlsb, 1) != 1) {
            perror("Failed to read temperature XLSB");
            continue;
        }

        // Calculate pressure and temperature
        int32_t pressure_raw = (pressure_msb << 16) | (pressure_lsb << 8) | pressure_xlsb;
        int32_t temp_raw = (temp_msb << 16) | (temp_lsb << 8) | temp_xlsb;

        // BMP280 datasheet provides calibration coefficients
        // These values should be read from the device and stored in variables
        // For simplicity, let's assume they are already known
        int32_t dig_T1 = 27400; // Example calibration coefficient
        int32_t dig_T2 = 8000;  // Example calibration coefficient
        int32_t dig_T3 = 3000;  // Example calibration coefficient
        int32_t dig_P1 = 31622; // Example calibration coefficient
        int32_t dig_P2 = 2575;  // Example calibration coefficient
        int32_t dig_P3 = 698;   // Example calibration coefficient
        int32_t dig_P4 = 52;    // Example calibration coefficient
        int32_t dig_P5 = 19;    // Example calibration coefficient
        int32_t dig_P6 = -1;    // Example calibration coefficient
        int32_t dig_P7 = 2;     // Example calibration coefficient
        int32_t dig_P8 = -1;    // Example calibration coefficient
        int32_t dig_P9 = 1;     // Example calibration coefficient

        // Calculate temperature
        int32_t var1 = (((temp_raw >> 3) - dig_T1) * dig_T2) >> 11;
        int32_t var2 = (((((temp_raw >> 4) - dig_T1) * (temp_raw >> 4) - dig_T3) >> 12) * dig_T4) >> 11;
        int32_t temp_fine = var1 + var2;
        float temp_c = (temp_fine * 5 + 128) >> 8;

        // Calculate pressure
        int64_t var1 = temp_fine - 128000;
        int64_t var2 = var1 * var1 * dig_P6;
        var2 += var1 * dig_P5 * 2;
        var2 += dig_P4;
        var1 *= var1 * dig_P3;
        var1 += var1 * dig_P2 * 2;
        var1 += dig_P1;
        int64_t p = var2 / (var1 + 1);
        float pressure_pa = p / 256.0;

        // Print the readings
        printf("Temperature: %.2f°C, Pressure: %.2f hPa\n", temp_c, pressure_pa);

        // Wait for 5 seconds before the next reading
        sleep(5);
    }

    // Cleanup on exit
    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define PWM_PIN 4

int main(void)
{
    int dutyCycle = 50; // Initial duty cycle percentage
    int period = 1000; // Period in microseconds

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up PWM on GPIO 4 with specified period and duty cycle
    if (gpioSetPWMfrequency(PWM_PIN, period) < 0)
    {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMdutyCycle(PWM_PIN, dutyCycle) < 0)
    {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Print the current state
    printf("PWM on GPIO %d set to duty cycle %d%%\n", PWM_PIN, dutyCycle);

    // Keep the program running until interrupted
    while (1)
    {
        // Simulate changing duty cycle
        dutyCycle += 10;
        if (dutyCycle > 100)
            dutyCycle = 0;

        // Update PWM duty cycle
        if (gpioSetPWMdutyCycle(PWM_PIN, dutyCycle) < 0)
        {
            fprintf(stderr, "Failed to update PWM duty cycle\n");
            break;
        }

        // Print the updated state
        printf("PWM on GPIO %d set to duty cycle %d%%\n", PWM_PIN, dutyCycle);
    }

    // Terminate pigpio library and release resources
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_5 5
#define GPIO_6 6
#define GPIO_13 13

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line[3];
    const char *consumer = "gpio_output";

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    // Request lines
    line[0] = gpiod_chip_get_line(chip, GPIO_5);
    line[1] = gpiod_chip_get_line(chip, GPIO_6);
    line[2] = gpiod_chip_get_line(chip, GPIO_13);

    if (!line[0] || !line[1] || !line[2]) {
        perror("Failed to get lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure lines as outputs
    for (int i = 0; i < 3; i++) {
        ret = gpiod_line_request_output(line[i], consumer, 0);
        if (ret) {
            perror("Failed to request line as output");
            gpiod_line_release(line[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Apply initial state
    for (int i = 0; i < 3; i++) {
        ret = gpiod_line_set_value(line[i], 1);
        if (ret) {
            perror("Failed to set line value");
            gpiod_line_release(line[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Main loop
    while (!should_exit) {
        sleep(1);
        printf("GPIO 5: %d, GPIO 6: %d, GPIO 13: %d\n",
               gpiod_line_get_value(line[0]),
               gpiod_line_get_value(line[1]),
               gpiod_line_get_value(line[2]));
    }

    // Release lines and chip
    for (int i = 0; i < 3; i++) {
        gpiod_line_release(line[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <paho-mqtt-c/mqtt_client.h>

// Define GPIO pin for the sensor
#define SENSOR_PIN 17

// MQTT broker details
const char* broker_address = "mqtt.eclipse.org";
const int broker_port = 1883;
const char* topic = "sensor/reading";

// MQTT client context
MQTTClient client;

// Signal handler to clean up resources on exit
void signal_handler(int signum) {
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (gpioInitialise() != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO pin as input
    if (gpioSetMode(SENSOR_PIN, PI_INPUT)) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Initialize MQTT client
    client = MQTTClient_create(NULL, broker_address, broker_port, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (!client) {
        fprintf(stderr, "Failed to create MQTT client\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Connect to MQTT broker
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 60;
    conn_opts.cleansession = 1;
    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Read sensor data
    int sensor_value = gpioRead(SENSOR_PIN);
    printf("Sensor value: %d\n", sensor_value);

    // Publish sensor reading to MQTT topic
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = (char*)&sensor_value;
    pubmsg.payloadlen = sizeof(sensor_value);
    pubmsg.qos = 1;
    pubmsg.retained = 0;
    if (MQTTClient_publish(client, topic, pubmsg.payloadlen, pubmsg.payload, pubmsg.qos, pubmsg.retained) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message\n");
    }

    // Disconnect from MQTT broker
    MQTTClient_disconnect(client, 1000);

    // Clean up resources
    MQTTClient_destroy(&client);
    gpioTerminate();

    return EXIT_SUCCESS;
}

