    result = gpioPWM(PWM_PIN_3, 500); // 500 Hz, 50% duty cycle
    if (result < 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", PWM_PIN_3, gpioErrDescription(result));
        goto cleanup;
    }
    result = gpioPWM(PWM_PIN_18, 500); // 500 Hz, 50% duty cycle
    if (result < 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", PWM_PIN_18, gpioErrDescription(result));
        goto cleanup;
    }
    result = gpioPWM(PWM_PIN_23, 500); // 500 Hz, 50% duty cycle
    if (result < 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", PWM_PIN_23, gpioErrDescription(result));
        goto cleanup;
    }
    result = gpioPWM(PWM_PIN_24, 500); // 500 Hz, 50% duty cycle
    if (result < 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", PWM_PIN_24, gpioErrDescription(result));
