    }
    if (gpioPWM(PWM_PIN_27, 0) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", PWM_PIN_27);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    while (keep_running) {
        // Toggle duty cycle between 0% and 100%
        for (int duty = 0; duty <= 100; duty += 10) {
            printf("Duty cycle: %d%%\n", duty);
            gpioPWM(PWM_PIN_17, duty);
            gpioPWM(PWM_PIN_22, duty);
            gpioPWM(PWM_PIN_27, duty);
            usleep(50000); // Sleep for 50 ms
        }
        for (int duty = 100; duty >= 0; duty -= 10) {
            printf("Duty cycle: %d%%\n", duty);
            gpioPWM(PWM_PIN_17, duty);
            gpioPWM(PWM_PIN_22, duty);
            gpioPWM(PWM_PIN_27, duty);
            usleep(50000); // Sleep for 50 ms
        }
    }

    // Clean up
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <libv4l2.h>

#define DEVICE "/dev/video0"
#define IMAGE_FILE "captured_image.jpg"
#define BUFFER_SIZE 2048 * 1024

static void usage(const char *progname) {
    fprintf(stderr, "Usage: %s\n", progname);
    exit(EXIT_FAILURE);
}

static void close_device(int fd) {
    if (close(fd) == -1) {
        perror("Failed to close device");
    }
}

static void close_buffers(int fd, struct v4l2_buffer *buffers, int num_buffers) {
    for (int i = 0; i < num_buffers; i++) {
        if (ioctl(fd, VIDIOC_QBUF, &buffers[i]) == -1) {
            perror("Failed to queue buffer");
        }
    }
}

static void free_buffers(struct v4l2_buffer *buffers, int num_buffers) {
    free(buffers);
}

static void close_format(int fd) {
    struct v4l2_format format;
    memset(&format, 0, sizeof(format));
    format.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_S_FMT, &format) == -1) {
        perror("Failed to set format");
    }
}

static void close_stream(int fd) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 0;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Failed to request buffers");
    }
}

static void close_device_and_buffers(int fd, struct v4l2_buffer *buffers, int num_buffers) {
    close_device(fd);
    close_buffers(fd, buffers, num_buffers);
    free_buffers(buffers, num_buffers);
}

static void close_format_and_stream(int fd) {
    close_format(fd);
    close_stream(fd);
}

static void close_all_resources(int fd, struct v4l2_buffer *buffers, int num_buffers) {
    close_device_and_buffers(fd, buffers, num_buffers);
    close_format_and_stream(fd);
}

static void capture_image(int fd, struct v4l2_buffer *buffers, int num_buffers) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Failed to dequeue buffer");
        return;
    }

    FILE *file = fopen(IMAGE_FILE, "wb");
    if (!file) {
        perror("Failed to open image file");
        close_device(fd);
        close_buffers(fd, buffers, num_buffers);
        free_buffers(buffers, num_buffers);
        return;
    }

    fwrite(buffers[buf.index].m.data, 1, buf.bytesused, file);
    fclose(file);

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Failed to queue buffer");
    }
}

static void signal_handler(int signum) {
    printf("Signal received, exiting...\n");
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    if (argc != 1) {
        usage(argv[0]);
    }

    int fd = open(DEVICE, O_RDWR | O_NONBLOCK);
    if (fd == -1) {
        perror("Failed to open device");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Failed to query capabilities");
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close_device(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Failed to set format");
        close_device(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Failed to request buffers");
        close_device(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer *buffers = malloc(req.count * sizeof(*buffers));
    if (!buffers) {
        perror("Failed to allocate buffers");
        close_device(fd);
        close_buffers(fd, buffers, req.count);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < req.count; i++) {
        memset(&buffers[i], 0, sizeof(buffers[i]));
        buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffers[i].memory = V4L2_MEMORY_MMAP;
        buffers[i].index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buffers[i]) == -1) {
            perror("Failed to query buffer");
            close_all_resources(fd, buffers, req.count);
            return EXIT_FAILURE;
        }

        void *data = mmap(NULL, buffers[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buffers[i].m.offset);
        if (data == MAP_FAILED) {
            perror("Failed to map buffer");
            close_all_resources(fd, buffers, req.count);
            return EXIT_FAILURE;
        }
        buffers[i].m.data = data;
    }

    for (int i = 0; i < req.count; i++) {
        if (ioctl(fd, VIDIOC_QBUF, &buffers[i]) == -1) {
            perror("Failed to queue buffer");
            close_all_resources(fd, buffers, req.count);
            return EXIT_FAILURE;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Failed to start streaming");
        close_all_resources(fd, buffers, req.count);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            perror("Failed to dequeue buffer");
            continue;
        }

        FILE *file = fopen(IMAGE_FILE, "wb");
        if (!file) {
            perror("Failed to open image file");
            close_device(fd);
            close_buffers(fd, buffers, req.count);
            free_buffers(buffers, req.count);
            return EXIT_FAILURE;
        }

        fwrite(buffers[buf.index].m.data, 1, buf.bytesused, file);
        fclose(file);

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Failed to queue buffer");
        }
    }

    close_all_resources(fd, buffers, req.count);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <libv4l2.h>

#define DEVICE "/dev/video0"
#define OUTPUT_FILE "captured_image.jpg"
#define WIDTH 640
#define HEIGHT 480
#define FRAMES 1

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *buffer;
    int i;

    // Open the video device
    fd = open(DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open video device");
        return EXIT_FAILURE;
    }

    // Check if the device is a video device
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Failed to query capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set the format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Failed to set format");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = FRAMES;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Failed to request buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffers
    buffer = malloc(req.bytesperbuffer * req.count);
    if (!buffer) {
        perror("Failed to allocate memory for buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    for (i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Failed to query buffer");
            free(buffer);
            close(fd);
            return EXIT_FAILURE;
        }

        if (mmap(buffer + buf.m.offset, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset) == MAP_FAILED) {
            perror("Failed to map buffer");
            free(buffer);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Queue the buffers
    for (i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Failed to queue buffer");
            munmap(buffer, req.bytesperbuffer * req.count);
            free(buffer);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Start streaming
    if (ioctl(fd, VIDIOC_STREAMON, &buf.type) == -1) {
        perror("Failed to start streaming");
        munmap(buffer, req.bytesperbuffer * req.count);
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Capture the image
    for (i = 0; i < FRAMES; i++) {
        fd_set fds;
        struct timeval tv;
        int ret;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 5; // Timeout after 5 seconds
        tv.tv_usec = 0;

        ret = select(fd + 1, &fds, NULL, NULL, &tv);
        if (ret == -1) {
            perror("Select failed");
            munmap(buffer, req.bytesperbuffer * req.count);
            free(buffer);
            close(fd);
            return EXIT_FAILURE;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout occurred while waiting for data\n");
            munmap(buffer, req.bytesperbuffer * req.count);
            free(buffer);
            close(fd);
            return EXIT_FAILURE;
        }

        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            perror("Failed to dequeue buffer");
            munmap(buffer, req.bytesperbuffer * req.count);
            free(buffer);
            close(fd);
            return EXIT_FAILURE;
        }

        // Write the captured image to a file
        FILE *file = fopen(OUTPUT_FILE, "wb");
        if (!file) {
            perror("Failed to open output file");
            munmap(buffer, req.bytesperbuffer * req.count);
            free(buffer);
            close(fd);
            return EXIT_FAILURE;
        }

        fwrite(buffer + buf.m.offset, buf.length, 1, file);
        fclose(file);

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Failed to queue buffer");
            munmap(buffer, req.bytesperbuffer * req.count);
            free(buffer);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &buf.type) == -1) {
        perror("Failed to stop streaming");
        munmap(buffer, req.bytesperbuffer * req.count);
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Unmap the buffers
    for (i = 0; i < req.count; i++) {
        munmap(buffer + buf.m.offset, buf.length);
    }

    // Free the allocated memory
    free(buffer);

    // Close the video device
    close(fd);

    printf("Image captured and saved to %s\n", OUTPUT_FILE);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_2 2
#define GPIO_3 3
#define INTERVAL 500000 // 0.5 seconds in microseconds

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int fd_gpio2, fd_gpio3;
    struct gpiod_chip *chip;
    struct gpiod_line *line2, *line3;
    const char *chip_name = "gpiochip0";
    const char *line_name2 = "gpio2";
    const char *line_name3 = "gpio3";

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the chip
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get lines
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        perror("Failed to get GPIO line 2");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        perror("Failed to get GPIO line 3");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines as outputs
    if (gpiod_line_request_output(line2, line_name2, 0)) {
        perror("Failed to request GPIO line 2 as output");
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line3, line_name3, 0)) {
        perror("Failed to request GPIO line 3 as output");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        // Toggle GPIO 2
        if (gpiod_line_set_value(line2, !gpiod_line_get_value(line2))) {
            perror("Failed to set GPIO line 2 value");
            break;
        }

        // Toggle GPIO 3
        if (gpiod_line_set_value(line3, !gpiod_line_get_value(line3))) {
            perror("Failed to set GPIO line 3 value");
            break;
        }

        // Sleep for 0.5 seconds
        usleep(INTERVAL);
    }

    // Release lines and close chip
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

