#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>

#define BAUDRATE B9600
#define DEVICE "/dev/ttyAMA0" // For Raspberry Pi 3/4
// #define DEVICE "/dev/ttyUSB0" // For USB-to-serial adapter

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int fd;
    struct termios options;

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the UART device
    fd = open(DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Failed to open UART device");
        return EXIT_FAILURE;
    }

    // Configure the UART port
    if (tcgetattr(fd, &options) != 0) {
        perror("Failed to get UART attributes");
        close(fd);
        return EXIT_FAILURE;
    }

    cfsetispeed(&options, BAUDRATE);
    cfsetospeed(&options, BAUDRATE);

    options.c_cflag &= ~PARENB; // No parity bit
    options.c_cflag &= ~CSTOPB; // One stop bit
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8; // 8 data bits

    options.c_cflag &= ~CRTSCTS; // Disable hardware flow control
    options.c_cflag |= CREAD | CLOCAL; // Enable receiver, ignore modem status lines

    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // Disable canonical mode, echo, echoE, and signal chars

    options.c_oflag &= ~OPOST; // Disable output processing

    if (tcsetattr(fd, TCSANOW, &options) != 0) {
        perror("Failed to set UART attributes");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("UART initialized successfully.\n");

    while (!should_exit) {
        unsigned char buffer[256];
        ssize_t bytes_read;

        bytes_read = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("Received: %s\n", buffer);
        } else if (bytes_read == 0) {
            printf("No data received.\n");
        } else {
            perror("Error reading from UART");
        }
    }

    // Close the UART device
    close(fd);

    printf("UART closed.\n");

    return EXIT_SUCCESS;
}

