#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_17 17
#define PWM_PIN_18 18
#define PWM_PIN_27 27

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int gpio_fd;
    int pwm_handle[3];
    int duty_cycle = 50; // Initial duty cycle percentage

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up PWM pins
    for (int i = 0; i < 3; i++) {
        gpio_fd = gpioGetGpioDesc(PWM_PIN_17 + i);
        if (gpio_fd < 0) {
            fprintf(stderr, "Failed to get GPIO descriptor for pin %d\n", PWM_PIN_17 + i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        pwm_handle[i] = gpioServo(gpio_fd, duty_cycle * 100);
        if (pwm_handle[i] < 0) {
            fprintf(stderr, "Failed to set PWM on pin %d\n", PWM_PIN_17 + i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (keep_running) {
        printf("Duty Cycle: %d%%\n", duty_cycle);
        fflush(stdout);
        usleep(500000); // Sleep for 0.5 seconds

        // Increment duty cycle and wrap around if necessary
        duty_cycle = (duty_cycle + 1) % 101;
    }

    // Clean up
    for (int i = 0; i < 3; i++) {
        gpioPWM(pwm_handle[i], 0); // Turn off PWM
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT_PIN 4
#define MAX_WAIT_TIME 1000000 // 1 second in microseconds

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    uint8_t data[5];
    int i, j;
    int humidity, temperature;
    int status;

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request a line for the DHT22
    line = gpiod_chip_get_line(chip, DHT_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the line as output
    status = gpiod_line_request_output(line, "dht22", 0);
    if (status) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Send start signal
    gpiod_line_set_value(line, 0); // Low
    usleep(200000); // 200 ms
    gpiod_line_set_value(line, 1); // High
    usleep(400000); // 400 ms

    // Read response
    for (i = 0; i < 5; i++) {
        data[i] = 0;
        for (j = 0; j < 8; j++) {
            while (gpiod_line_get_value(line)) {
                if (--MAX_WAIT_TIME <= 0) {
                    fprintf(stderr, "DHT22 did not respond\n");
                    gpiod_line_release(line);
                    gpiod_chip_close(chip);
                    return EXIT_FAILURE;
                }
            }
            usleep(28000); // 28 us
            if (gpiod_line_get_value(line)) {
                data[i] |= (1 << j);
            }
            usleep(7000); // 70 us
        }
    }

    // Release line
    gpiod_line_release(line);

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "Checksum error\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Calculate humidity and temperature
    humidity = ((data[0] << 8) | data[1]) / 10.0;
    temperature = ((data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) {
        temperature *= -1;
    }

    // Print result
    printf("Humidity: %.1f%%, Temperature: %.1f°C\n", humidity, temperature);

    // Close chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

