void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[5];
    int ret;

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    for (int i = 0; i < 5; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            perror("Failed to get line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Set direction to output
    for (int i = 0; i < 5; i++) {
        ret = gpiod_line_request_output(lines[i], "my_program", 0);
