#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <paho-mqtt-c/paho-mqttc.h>

// Define constants
#define MQTT_BROKER "mqtt.example.com"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/data"
#define MCP3008_CS_PIN 8
#define MCP3008_CLK_PIN 9
#define MCP3008_DOUT_PIN 10

// Global variables
MQTTClient client;
MQTTClient_connectOptions conn_opts;
MQTTClient_message pubmsg;
MQTTClient_deliveryToken token;

void on_connect(void *context, MQTTClient_deliveryToken dt) {
    printf("Connected with token %d\n", dt);
}

void on_publish(void *context, MQTTClient_deliveryToken dt) {
    printf("Publish completed with token %d\n", dt);
}

void on_error(void *context, char *error_str) {
    fprintf(stderr, "Error: %s\n", error_str);
}

void on_disconnect(void *context, int rc) {
    printf("Disconnected with return code %d\n", rc);
}

void on_messageArrived(void *context, MQTTClient_message *message) {
    printf("Message arrived: %.*s\n", message->payloadlen, message->payload);
    MQTTClient_freeMessage(&message);
}

void signal_handler(int sig) {
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize MQTT client
    client = MQTTClient_create(NULL, MQTT_BROKER, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (!client) {
        fprintf(stderr, "Failed to create MQTT client\n");
        return 1;
    }

    // Set connection options
    conn_opts.keepAliveInterval = 60;
    conn_opts.cleansession = 1;
    conn_opts.username = "your_username";
    conn_opts.password = "your_password";

    // Connect to MQTT broker
    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        MQTTClient_destroy(&client);
        return 1;
    }

    // Subscribe to the MQTT topic
    if (MQTTClient_subscribe(client, MQTT_TOPIC, 0) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to subscribe to MQTT topic\n");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return 1;
    }

    // Initialize libgpiod
    const char *chip_name = "gpiochip0";
    struct gpiod_chip *chip = gpiod_chip_open(chip_name);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open GPIO lines
    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, MCP3008_CS_PIN);
    struct gpiod_line *clk_line = gpiod_chip_get_line(chip, MCP3008_CLK_PIN);
    struct gpiod_line *dout_line = gpiod_chip_get_line(chip, MCP3008_DOUT_PIN);

    if (!cs_line || !clk_line || !dout_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return 1;
    }

    // Request the line as output
    if (gpiod_line_request_output(cs_line, "mcp3008_cs", 0) != 0 ||
        gpiod_line_request_output(clk_line, "mcp3008_clk", 0) != 0 ||
        gpiod_line_request_input(dout_line, "mcp3008_dout") != 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_line_release(cs_line);
        gpiod_line_release(clk_line);
        gpiod_line_release(dout_line);
        gpiod_chip_close(chip);
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return 1;
    }

    // Main loop to read sensor data and publish
    while (1) {
        // Start conversion
        gpiod_line_set_value(cs_line, 0);
        usleep(1000);
        gpiod_line_set_value(clk_line, 1);
        usleep(1000);
        gpiod_line_set_value(clk_line, 0);
        usleep(1000);
        gpiod_line_set_value(cs_line, 1);

        // Read data
        uint8_t data[3];
        for (int i = 0; i < 3; i++) {
            data[i] = gpiod_line_get_value(dout_line);
            usleep(1000);
            gpiod_line_set_value(clk_line, 1);
            usleep(1000);
            gpiod_line_set_value(clk_line, 0);
            usleep(1000);
        }

        // Convert data to 10-bit value
        uint16_t adc_value = (data[1] << 8) | data[2];

        // Publish the reading
        pubmsg.payload = (char *)&adc_value;
        pubmsg.payloadlen = sizeof(adc_value);
        pubmsg.qos = 0;
        pubmsg.retained = 0;

        if (MQTTClient_publish(client, MQTT_TOPIC, pubmsg.payloadlen, pubmsg.payload, pubmsg.qos, pubmsg.retained, &token) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish message\n");
        } else {
            MQTTClient_waitForCompletion(client, token, 10000);
        }

        // Delay before next reading
        usleep(1000000);
    }

    // Clean up
    gpiod_line_release(cs_line);
    gpiod_line_release(clk_line);
    gpiod_line_release(dout_line);
    gpiod_chip_close(chip);
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE "/dev/video0"
#define OUTPUT_FILE "captured_image.jpg"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *buffer;
    int ret;

    // Open the video device
    fd = open(DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open video device");
        return EXIT_FAILURE;
    }

    // Query capabilities
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret == -1) {
        perror("Failed to query capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    // Check if the device is a video capture device
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret == -1) {
        perror("Failed to set format");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret == -1) {
        perror("Failed to request buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    // Map buffers
    buffer = mmap(NULL, req.count * fmt.fmt.pix.sizeimage, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Failed to map buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    // Queue buffers
    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.index = i;
        buf.m.mem_offset = buffer + i * fmt.fmt.pix.sizeimage;

        ret = ioctl(fd, VIDIOC_QBUF, &buf);
        if (ret == -1) {
            perror("Failed to queue buffer");
            munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ret = ioctl(fd, VIDIOC_STREAMON, &type);
    if (ret == -1) {
        perror("Failed to start streaming");
        munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
        close(fd);
        return EXIT_FAILURE;
    }

    // Wait for a frame
    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    struct timeval tv;
    tv.tv_sec = 5; // Timeout after 5 seconds
    tv.tv_usec = 0;

    ret = select(fd + 1, &fds, NULL, NULL, &tv);
    if (ret == -1) {
        perror("Select failed");
        munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
        close(fd);
        return EXIT_FAILURE;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout occurred\n");
        munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
        close(fd);
        return EXIT_FAILURE;
    }

    // Dequeue buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_DQBUF, &buf);
    if (ret == -1) {
        perror("Failed to dequeue buffer");
        munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
        close(fd);
        return EXIT_FAILURE;
    }

    // Write the captured image to a file
    FILE *file = fopen(OUTPUT_FILE, "wb");
    if (file == NULL) {
        perror("Failed to open output file");
        munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
        close(fd);
        return EXIT_FAILURE;
    }

    fwrite(buffer + buf.m.mem_offset, 1, buf.bytesused, file);
    fclose(file);

    // Stop streaming
    ret = ioctl(fd, VIDIOC_STREAMOFF, &type);
    if (ret == -1) {
        perror("Failed to stop streaming");
        munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
        close(fd);
        return EXIT_FAILURE;
    }

    // Unmap buffers
    munmap(buffer, req.count * fmt.fmt.pix.sizeimage);

    // Close the video device
    close(fd);

    printf("Image captured and saved as %s\n", OUTPUT_FILE);
    return EXIT_SUCCESS;
}

