            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_gpios; i++) {
        if (gpioPWM(gpio_pins[i], PWM_DUTY_CYCLE * PWM_FREQ / 100) < 0) {
            fprintf(stderr, "Failed to set PWM for GPIO %d\n", gpio_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("PWM output started on GPIOs: ");
    for (int i = 0; i < num_gpios; i++) {
        printf("%d ", gpio_pins[i]);
    }
    printf("\n");

    // Set up interrupt handler
    gpioSetAlertFuncEx(PI_GPIO_ALL, interruptHandler);

    // Keep the program running until interrupted
    while (1) {
        sleep(1);
    }

    // Clean up resources
    gpioTerminate();

    return EXIT_SUCCESS;
}

