#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    const char *chip_name = "gpiochip0";
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    int trigger_value = 0;
    int echo_value = 0;
    long duration_us = 0;
    double distance_cm = 0.0;
    struct timespec sleep_time = {1, 0}; // 1 second

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines
    if (gpiod_line_request_output(trigger_line, "trigger", 0)) {
        perror("Failed to request trigger line");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo_line, "echo")) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (!should_exit) {
        // Trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        usleep(10); // Wait for 10 microseconds
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo pulse
        while ((echo_value = gpiod_line_get_value(echo_line)) == 0) {
            if (should_exit) {
                break;
            }
            usleep(10);
        }

        if (should_exit) {
            break;
        }

        struct timespec start_time, end_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        while ((echo_value = gpiod_line_get_value(echo_line)) != 0) {
            if (should_exit) {
                break;
            }
            usleep(10);
        }

        if (should_exit) {
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &end_time);

        duration_us = (end_time.tv_sec - start_time.tv_sec) * 1000000 +
                      (end_time.tv_nsec - start_time.tv_nsec) / 1000;

        if (duration_us > 0) {
            distance_cm = duration_us / 58.26; // Speed of sound in cm/us
            printf("Distance: %.2f cm\n", distance_cm);
        } else {
            printf("Error: No response from sensor\n");
        }

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Release resources
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_FREQ 5000 // Frequency in Hz
#define PWM_DUTY_CYCLE 50 // Duty cycle in percentage

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    // Set up PWM on GPIOs 8, 9, 11, 18
    if (gpioSetMode(8, PI_OUTPUT) != PI_OK ||
        gpioSetMode(9, PI_OUTPUT) != PI_OK ||
        gpioSetMode(11, PI_OUTPUT) != PI_OK ||
        gpioSetMode(18, PI_OUTPUT) != PI_OK) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(8, PWM_DUTY_CYCLE) != PI_OK ||
        gpioPWM(9, PWM_DUTY_CYCLE) != PI_OK ||
        gpioPWM(11, PWM_DUTY_CYCLE) != PI_OK ||
        gpioPWM(18, PWM_DUTY_CYCLE) != PI_OK) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sa.sa_flags = 0;
    if (sigemptyset(&sa.sa_mask) != 0 || sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        printf("PWM duty cycle: %d%%\n", PWM_DUTY_CYCLE);
        sleep(1);
    }

    // Clean up
    gpioPWM(8, 0);
    gpioPWM(9, 0);
    gpioPWM(11, 0);
    gpioPWM(18, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <libv4l2.h>

#define DEVICE "/dev/video0"
#define IMAGE_FILE "captured_image.jpg"
#define BUFFER_SIZE 2048 * 1024

static void usage(const char *progname) {
    fprintf(stderr, "Usage: %s\n", progname);
    exit(EXIT_FAILURE);
}

static void close_device(int fd) {
    if (close(fd) == -1) {
        perror("Failed to close device");
    }
}

static void free_buffers(void **buffers, int count) {
    for (int i = 0; i < count; i++) {
        free(buffers[i]);
    }
}

static void free_context(struct v4l2_context *ctx) {
    free_context(ctx->buffers);
    free_context(ctx->stream);
    free(ctx);
}

static struct v4l2_context *init_context(void) {
    struct v4l2_context *ctx = malloc(sizeof(*ctx));
    if (!ctx) {
        perror("Failed to allocate context");
        return NULL;
    }

    ctx->buffers = malloc(BUFFER_COUNT * sizeof(*ctx->buffers));
    if (!ctx->buffers) {
        perror("Failed to allocate buffers");
        free_context(ctx);
        return NULL;
    }

    ctx->stream = malloc(sizeof(*ctx->stream));
    if (!ctx->stream) {
        perror("Failed to allocate stream");
        free_context(ctx);
        return NULL;
    }

    return ctx;
}

static int init_device(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Failed to query capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Failed to set format");
        return -1;
    }

    return 0;
}

static int init_buffers(int fd, struct v4l2_context *ctx) {
    struct v4l2_requestbuffers req;
    int i;

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Failed to request buffers");
        return -1;
    }

    ctx->buffers = malloc(req.count * sizeof(*ctx->buffers));
    if (!ctx->buffers) {
        perror("Failed to allocate buffers");
        return -1;
    }

    for (i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Failed to query buffer");
            return -1;
        }

        ctx->buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (ctx->buffers[i] == MAP_FAILED) {
            perror("Failed to map buffer");
            return -1;
        }
    }

    return 0;
}

static int queue_buffers(int fd, struct v4l2_context *ctx) {
    struct v4l2_buffer buf;
    int i;

    for (i = 0; i < BUFFER_COUNT; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Failed to queue buffer");
            return -1;
        }
    }

    return 0;
}

static int start_streaming(int fd, struct v4l2_context *ctx) {
    struct v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Failed to start streaming");
        return -1;
    }

    return 0;
}

static int capture_image(int fd, struct v4l2_context *ctx) {
    struct v4l2_buffer buf;
    int i;

    for (i = 0; i < BUFFER_COUNT; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            perror("Failed to dequeue buffer");
            return -1;
        }

        FILE *file = fopen(IMAGE_FILE, "wb");
        if (!file) {
            perror("Failed to open image file");
            return -1;
        }

        fwrite(ctx->buffers[i], buf.bytesused, 1, file);
        fclose(file);

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Failed to queue buffer after capture");
            return -1;
        }
    }

    return 0;
}

static void stop_streaming(int fd, struct v4l2_context *ctx) {
    struct v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Failed to stop streaming");
    }
}

static void cleanup(int fd, struct v4l2_context *ctx) {
    stop_streaming(fd, ctx);
    free_buffers(ctx->buffers, BUFFER_COUNT);
    free_context(ctx);
    close_device(fd);
}

static void signal_handler(int signum) {
    printf("Signal received, exiting...\n");
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    int fd;
    struct v4l2_context *ctx;
    struct sigaction sa;

    if (argc != 1) {
        usage(argv[0]);
    }

    // Register signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open device
    fd = open(DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open device");
        return EXIT_FAILURE;
    }

    // Initialize context
    ctx = init_context();
    if (!ctx) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Initialize device
    if (init_device(fd) == -1) {
        free_context(ctx);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Initialize buffers
    if (init_buffers(fd, ctx) == -1) {
        free_context(ctx);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Queue buffers
    if (queue_buffers(fd, ctx) == -1) {
        free_context(ctx);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(fd, ctx) == -1) {
        free_context(ctx);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Capture images
    while (1) {
        if (capture_image(fd, ctx) == -1) {
            free_context(ctx);
            close_device(fd);
            return EXIT_FAILURE;
        }
        usleep(100000); // Sleep for 0.1 seconds
    }

    // Cleanup
    cleanup(fd, ctx);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Global variable to store the handle to the GPIO
int gpio_handle = -1;

// Signal handler to clean up on interrupt
void signal_handler(int signum) {
    if (gpio_handle != -1) {
        // Stop PWM
        gpioPWMWrite(gpio_handle, 18, 0);
        // Release GPIO
        gpioTerminate();
    }
    printf("Program terminated by signal %d\n", signum);
    exit(EXIT_SUCCESS);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }
    gpio_handle = gpioGetChipHandle(0);

    // Set GPIO 18 as PWM output
    if (gpioSetMode(gpio_handle, 18, PI_OUTPUT_PWM) < 0) {
        fprintf(stderr, "Failed to set GPIO 18 mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set PWM frequency to 100 Hz
    if (gpioSetPWMfrequency(gpio_handle, 18, 100) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Apply different PWM duty cycles
        for (int duty_cycle = 0; duty_cycle <= 100; duty_cycle += 10) {
            gpioPWMWrite(gpio_handle, 18, duty_cycle);
            printf("Duty cycle: %d%%\n", duty_cycle);
            sleep(1);
        }
        for (int duty_cycle = 100; duty_cycle >= 0; duty_cycle -= 10) {
            gpioPWMWrite(gpio_handle, 18, duty_cycle);
            printf("Duty cycle: %d%%\n", duty_cycle);
            sleep(1);
        }
    }

    // Clean up on exit
    gpioTerminate();

    return EXIT_SUCCESS;
}

