        // Send a pulse to the trigger pin
        trigger_value = 1;
        ret = gpiod_line_set_value(trigger_line, trigger_value);
        if (ret) {
            perror("Failed to set trigger value");
            break;
        }
        usleep(10); // Wait for the pulse to propagate

        // Wait for the echo pin to go high
        ret = gpiod_line_event_wait(echo_line, NULL);
        if (ret) {
            perror("Failed to wait for echo event");
            break;
        }

        // Read the echo pin value
        ret = gpiod_line_get_value(echo_line, &echo_value);
        if (ret) {
            perror("Failed to read echo value");
            break;
        }

        // Measure the duration of the pulse
        start_time = gpiod_line_event_timestamp_ns(echo_line);
        if (start_time == -1) {
            perror("Failed to get start time");
            break;
        }

        // Wait for the echo pin to go low
        ret = gpiod_line_event_wait(echo_line, NULL);
        if (ret) {
            perror("Failed to wait for echo event");
            break;
        }

