        ret = gpiod_line_get_value(echo_line, &echo_value);
        if (ret) {
            perror("Failed to read echo value");
            break;
        }

        // Measure the duration of the pulse
        end_time = gpiod_line_event_timestamp_ns(echo_line);
        if (end_time == -1) {
            perror("Failed to get end time");
            break;
        }

        // Calculate the distance in centimeters
        duration = (end_time - start_time) / 1000000.0;
        distance = duration * 0.0343; // Speed of sound in air is approximately 343 m/s

        // Print the distance
