#define SHT31_ADDR 0x44
#define SHT31_CMD_MEASURE_TEMP_HUMIDITY 0x24
#define SHT31_CMD_READ_STATUS 0xF3
#define SHT31_CMD_CLEAR_STATUS 0x30
#define SHT31_STATUS_OVF 0x08

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *gpio;

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (gpio) {
        gpiod_line_release(gpio);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int read_sht31_data(float *temperature, float *humidity) {
    uint8_t buffer[6];
    int ret;

    // Send measurement command
    ret = write(i2c_fd, &SHT31_CMD_MEASURE_TEMP_HUMIDITY, 1);
    if (ret != 1) {
        perror("Failed to send measurement command");
        return -1;
    }

    // Wait for measurement to complete
    usleep(15000);

    // Read status register
    ret = read(i2c_fd, buffer, 1);
    if (ret != 1) {
        perror("Failed to read status register");
        return -1;
    }

    // Check for overflow
    if (buffer[0] & SHT31_STATUS_OVF) {
        fprintf(stderr, "Overflow detected in SHT31\n");
        return -1;
    }

    // Read temperature and humidity data
    ret = read(i2c_fd, buffer, 6);
    if (ret != 6) {
        perror("Failed to read temperature and humidity data");
        return -1;
    }

    // Convert raw data to temperature and humidity
    *temperature = ((buffer[0] << 8) | buffer[1]) / 100.0f;
    *humidity = ((buffer[3] << 8) | buffer[4]) / 100.0f;

    return 0;
}

