    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    gpio_num = gpiod_chip_get_line(chip, 0);
    if (gpio_num < 0) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    gpio = gpiod_line_request_input(chip, gpio_num, GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN);
    if (!gpio) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(gpio_num);
        return EXIT_FAILURE;
    }

    // Open I2C device
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_chip_close(chip);
        gpiod_line_release(gpio_num);
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDR);
