#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_NUMBERS {5, 6, 12, 16, 19, 20, 23, 24, 25, 26}
#define NUM_GPIO 10

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_bulk *lines;
    unsigned int line_values[NUM_GPIO];
    const char *chip_name = "gpiochip0";

    // Register signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    lines = gpiod_chip_get_lines(chip, GPIO_NUMBERS, NUM_GPIO);
    if (!lines) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set direction of each line to output
    for (int i = 0; i < NUM_GPIO; i++) {
        ret = gpiod_line_request_output(lines, GPIO_NUMBERS[i], 0);
        if (ret) {
            perror("Failed to set GPIO line direction");
            gpiod_line_release_bulk(lines);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Apply high level to each line
    for (int i = 0; i < NUM_GPIO; i++) {
        line_values[i] = 1;
    }
    ret = gpiod_line_set_values_bulk(lines, line_values, NUM_GPIO);
    if (ret) {
        perror("Failed to set GPIO line values");
        gpiod_line_release_bulk(lines);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Report the state applied to standard output
    printf("GPIO lines 5-26 set to high level.\n");

    // Wait for interrupt or termination
    while (!should_exit) {
        sleep(1);
    }

    // Release the hardware
    gpiod_line_release_bulk(lines);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    const char *chip_name = "gpiochip0";
    struct gpiod_chip *chip;
    struct gpiod_line *line[3];
    int ret;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    line[0] = gpiod_chip_get_line(chip, GPIO_17);
    line[1] = gpiod_chip_get_line(chip, GPIO_22);
    line[2] = gpiod_chip_get_line(chip, GPIO_27);

    if (!line[0] || !line[1] || !line[2]) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set direction to output
    for (int i = 0; i < 3; i++) {
        ret = gpiod_line_request_output(line[i], "my_program", 0);
        if (ret) {
            perror("Failed to set GPIO line direction");
            gpiod_line_release(line[0]);
            gpiod_line_release(line[1]);
            gpiod_line_release(line[2]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    while (!should_exit) {
        // Toggle each line
        for (int i = 0; i < 3; i++) {
            ret = gpiod_line_set_value(line[i], !gpiod_line_get_value(line[i]));
            if (ret) {
                perror("Failed to set GPIO line value");
                break;
            }
        }

        // Report the state
        printf("GPIO 17: %d, GPIO 22: %d, GPIO 27: %d\n",
               gpiod_line_get_value(line[0]),
               gpiod_line_get_value(line[1]),
               gpiod_line_get_value(line[2]));

        // Sleep for 1 second
        sleep(1);
    }

    // Release lines and close chip
    for (int i = 0; i < 3; i++) {
        gpiod_line_release(line[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_17 17
#define PWM_PIN_18 18
#define PWM_PIN_22 22
#define PWM_PIN_27 27

static volatile sig_atomic_t quit = 0;

void signal_handler(int signum) {
    quit = 1;
}

int main() {
    int result;

    // Initialize pigpio library
    result = gpioInitialise();
    if (result < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioErrDescription(result));
        return EXIT_FAILURE;
    }

    // Set up PWM pins
    result = gpioSetMode(PWM_PIN_17, PI_OUTPUT);
    if (result < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d: %s\n", PWM_PIN_17, gpioErrDescription(result));
        goto cleanup;
    }
    result = gpioSetMode(PWM_PIN_18, PI_OUTPUT);
    if (result < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d: %s\n", PWM_PIN_18, gpioErrDescription(result));
        goto cleanup;
    }
    result = gpioSetMode(PWM_PIN_22, PI_OUTPUT);
    if (result < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d: %s\n", PWM_PIN_22, gpioErrDescription(result));
        goto cleanup;
    }
    result = gpioSetMode(PWM_PIN_27, PI_OUTPUT);
    if (result < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d: %s\n", PWM_PIN_27, gpioErrDescription(result));
        goto cleanup;
    }

    // Set PWM frequency and duty cycle
    result = gpioPWM(PWM_PIN_17, 500); // 500 Hz, 50% duty cycle
    if (result < 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", PWM_PIN_17, gpioErrDescription(result));
        goto cleanup;
    }
    result = gpioPWM(PWM_PIN_18, 500); // 500 Hz, 50% duty cycle
    if (result < 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", PWM_PIN_18, gpioErrDescription(result));
        goto cleanup;
    }
    result = gpioPWM(PWM_PIN_22, 500); // 500 Hz, 50% duty cycle
    if (result < 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", PWM_PIN_22, gpioErrDescription(result));
        goto cleanup;
    }
    result = gpioPWM(PWM_PIN_27, 500); // 500 Hz, 50% duty cycle
    if (result < 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", PWM_PIN_27, gpioErrDescription(result));
        goto cleanup;
    }

    // Report the state
    printf("PWM output applied to GPIOs 17, 18, 22, 27.\n");

    // Handle signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!quit) {
        sleep(1); // Keep the program running
    }

cleanup:
    // Release resources
    gpioTerminate();

    return EXIT_FAILURE;
}

