#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 24

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    enum gpiod_line_value value = GPIOD_LINE_VALUE_LOW;

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the line as output
    if (gpiod_line_request_output(line, "output", 0)) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Toggle the line
        value = (value == GPIOD_LINE_VALUE_LOW) ? GPIOD_LINE_VALUE_HIGH : GPIOD_LINE_VALUE_LOW;
        if (gpiod_line_set_value(line, value)) {
            perror("Failed to set GPIO line value");
        }
        printf("GPIO %d: %s\n", GPIO_PIN, (value == GPIOD_LINE_VALUE_LOW) ? "LOW" : "HIGH");

        // Sleep for 0.05 seconds
        usleep(50000);
    }

    // Release the line and chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE "/dev/video0"
#define OUTPUT_FILE "captured_image.jpg"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *buffer;
    int ret;

    // Open the video device
    fd = open(DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open video device");
        return EXIT_FAILURE;
    }

    // Query capabilities
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret == -1) {
        perror("Failed to query capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    // Check if the device is a video capture device
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret == -1) {
        perror("Failed to set format");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret == -1) {
        perror("Failed to request buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    // Map buffers
    buffer = mmap(NULL, req.count * fmt.fmt.pix.sizeimage, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Failed to map buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    // Queue buffers
    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.index = i;
        buf.m.mem_offset = buffer[i] * fmt.fmt.pix.sizeimage;

        ret = ioctl(fd, VIDIOC_QBUF, &buf);
        if (ret == -1) {
            perror("Failed to queue buffer");
            munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ret = ioctl(fd, VIDIOC_STREAMON, &type);
    if (ret == -1) {
        perror("Failed to start streaming");
        munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
        close(fd);
        return EXIT_FAILURE;
    }

    // Wait for a frame
    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    struct timeval tv;
    tv.tv_sec = 5;
    tv.tv_usec = 0;

    ret = select(fd + 1, &fds, NULL, NULL, &tv);
    if (ret == -1) {
        perror("Select failed");
        munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
        close(fd);
        return EXIT_FAILURE;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
        close(fd);
        return EXIT_FAILURE;
    }

    // Dequeue buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_DQBUF, &buf);
    if (ret == -1) {
        perror("Failed to dequeue buffer");
        munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
        close(fd);
        return EXIT_FAILURE;
    }

    // Save the image
    FILE *file = fopen(OUTPUT_FILE, "wb");
    if (file == NULL) {
        perror("Failed to open output file");
        munmap(buffer, req.count * fmt.fmt.pix.sizeimage);
        close(fd);
        return EXIT_FAILURE;
    }

    fwrite(buffer[buf.index], 1, fmt.fmt.pix.sizeimage, file);
    fclose(file);

    // Unmap buffers
    munmap(buffer, req.count * fmt.fmt.pix.sizeimage);

    // Stop streaming
    ret = ioctl(fd, VIDIOC_STREAMOFF, &type);
    if (ret == -1) {
        perror("Failed to stop streaming");
        close(fd);
        return EXIT_FAILURE;
    }

    // Close the video device
    close(fd);

    printf("Image saved to %s\n", OUTPUT_FILE);
    return EXIT_SUCCESS;
}

