#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 18

static volatile sig_atomic_t quit = 0;

void signal_handler(int signum) {
    quit = 1;
}

int main() {
    int i, j;
    uint32_t color = 0x00FF00; // Green color

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    if (gpioWrite(LED_PIN, 1)) {
        fprintf(stderr, "Failed to set LED pin high\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!quit) {
        for (i = 0; i < 3; i++) {
            for (j = 0; j < 256; j++) {
                color = (color << 1) | (j & 1);
                gpioPWM(LED_PIN, color);
                usleep(5000);
            }
            color = 0x00FF00; // Reset to green
        }
        usleep(50000); // Wait for 50 ms between cycles
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

