    // Request the line as input
    if (gpiod_line_request_input(line, "ds18b20")) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        cleanup();
        return EXIT_FAILURE;
    }

    // Open the W1 device file
    snprintf(path, sizeof(path), "%s/%s/w1_slave", W1_BUS, W1_DEVICE_FILE);
    w1_device_fd = open(path, O_RDONLY);
    if (w1_device_fd == -1) {
        perror("Failed to open W1 device file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Reading temperature every 5 seconds...\n");

    for (i = 0; i < 3; i++) {
        // Wait for the device to be ready
        while ((bytes_read = read(w1_device_fd, buffer, sizeof(buffer))) <= 0) {
            if (bytes_read == -1 && errno != EAGAIN) {
                perror("Failed to read from W1 device file");
                break;
            }
            usleep(100000); // Sleep for 100ms
        }

        if (bytes_read > 0) {
            // Parse the temperature from the response
            char *temp_start = strstr(buffer, "t=");
            if (temp_start) {
                temp_start += 2; // Skip 't='
                long temp_celsius = strtol(temp_start, NULL, 10);
                printf("Temperature: %.2f°C\n", (float)temp_celsius / 1000.0);
            } else {
                printf("Failed to parse temperature from response\n");
            }
        } else {
            printf("Device not found\n");
            break;
        }

        // Wait for 5 seconds before the next reading
        sleep(5);
    }

    // Clean up resources
    cleanup();

    return EXIT_SUCCESS;
}

