#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define BAUD_RATE 9600

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int fd_trigger, fd_echo;
    struct gpiod_chip *chip;
    struct gpiod_line *line_trigger, *line_echo;
    struct timespec start, end;
    long duration;
    double distance;
    char buffer[256];

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open the chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    // Get the lines
    line_trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    line_echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!line_trigger || !line_echo) {
        perror("Failed to get lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the lines for output and input
    if (gpiod_line_request_output(line_trigger, "trigger", 0) < 0 ||
        gpiod_line_request_input(line_echo, "echo") < 0) {
        perror("Failed to request lines");
        gpiod_line_release(line_trigger);
        gpiod_line_release(line_echo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        // Send a pulse to the trigger pin
        gpiod_line_set_value(line_trigger, 1);
        usleep(10); // Short delay
        gpiod_line_set_value(line_trigger, 0);

        // Wait for the echo pin to go high
        while (gpiod_line_get_value(line_echo) == 0) {
            if (should_exit) {
                break;
            }
        }

        // Measure the duration of the pulse
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line_echo) == 1) {
            if (should_exit) {
                break;
            }
        }
        clock_gettime(CLOCK_MONOTONIC, &end);

        duration = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);
        if (duration > 0) {
            // Calculate the distance in centimeters
            distance = (duration / 2.0) * 0.0343; // Speed of sound in cm/s

            // Print the distance
            snprintf(buffer, sizeof(buffer), "Distance: %.2f cm\n", distance);
            write(STDOUT_FILENO, buffer, strlen(buffer));
        } else {
            // Handle timeout
            snprintf(buffer, sizeof(buffer), "Timeout\n");
            write(STDOUT_FILENO, buffer, strlen(buffer));
        }

        // Wait for 0.1 seconds
        usleep(100000);
    }

    // Release the lines
    gpiod_line_release(line_trigger);
    gpiod_line_release(line_echo);

    // Close the chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

