    for (int i = 0; i < 3; i++) {
        line[i] = gpiod_chip_get_line(chip, line_names[i]);
        if (!line[i]) {
            perror("Failed to get GPIO line");
            ret = gpiod_chip_close(chip);
            if (ret) {
                perror("Failed to close GPIO chip");
