#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_4 4
#define PWM_PIN_17 17
#define PWM_PIN_18 18

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    // Set up PWM pins
    if (gpioSetMode(PWM_PIN_4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", PWM_PIN_4);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", PWM_PIN_17);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", PWM_PIN_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set PWM frequency to 50 Hz
    if (gpioSetPWMfrequency(PWM_PIN_4, 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_PIN_4);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_17, 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_PIN_17);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_18, 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_PIN_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set PWM range to 1000
    if (gpioSetPWMrange(PWM_PIN_4, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", PWM_PIN_4);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_17, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", PWM_PIN_17);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_18, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", PWM_PIN_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    while (keep_running) {
        // Generate a 50% duty cycle for each pin
        if (gpioPWM(PWM_PIN_4, 500) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", PWM_PIN_4);
            break;
        }
        if (gpioPWM(PWM_PIN_17, 500) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", PWM_PIN_17);
            break;
        }
        if (gpioPWM(PWM_PIN_18, 500) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", PWM_PIN_18);
            break;
        }

        // Report the state
        printf("PWM: 4=500, 17=500, 18=500\n");

        // Wait for 0.1 seconds
        usleep(100000);
    }

    // Clean up
    gpioTerminate();

    return EXIT_SUCCESS;
}

