#define TIMEOUT_MS 1000

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int chip_fd, line_fd;
    struct gpiod_line *line;
    uint8_t data[5] = {0};
    int i, j, k, sum, valid;
    struct timespec timeout = {0, TIMEOUT_MS * 1000000};

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip_fd = gpiod_chip_open_by_name("gpiochip0");
    if (chip_fd < 0) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request a line from the chip
    line_fd = gpiod_chip_get_line(chip_fd, DHT_PIN);
    if (line_fd < 0) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip_fd);
        return EXIT_FAILURE;
    }

    // Configure the line as input
    if (gpiod_line_request_input(line_fd, "dht22")) {
        perror("Failed to request GPIO line input");
        gpiod_line_release(line_fd);
        gpiod_chip_close(chip_fd);
        return EXIT_FAILURE;
    }

    // Read the data
    for (i = 0; i < MAX_READS; i++) {
        // Start signal
        gpiod_line_set_value(line_fd, 0);
        usleep(200000);
        gpiod_line_set_value(line_fd, 1);
        usleep(400000);

        // Wait for response
        if (gpiod_line_event_wait(line_fd, &timeout) < 0) {
            fprintf(stderr, "Timeout waiting for response\n");
            continue;
        }

        // Read data
        for (j = 0; j < 5; j++) {
            sum = 0;
            for (k = 0; k < 8; k++) {
                if (gpiod_line_event_wait(line_fd, &timeout) < 0) {
                    fprintf(stderr, "Timeout waiting for bit %d of byte %d\n", k, j);
                    break;
                }
                if (gpiod_line_event_get_value(line_fd)) {
                    sum |= (1 << (7 - k));
                }
            }
            data[j] = sum;
        }

        // Check checksum
        valid = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
        if (valid == data[4]) {
            printf("Temperature: %.2f°C, Humidity: %.2f%%\n", (data[0] << 8 | data[1]) / 10.0, (data[2] << 8 | data[3]) / 10.0);
            break;
        } else {
            fprintf(stderr, "Checksum error\n");
        }
    }

    // Release resources
    gpiod_line_release(line_fd);
    gpiod_chip_close(chip_fd);

    return EXIT_SUCCESS;
}

