            gpioSetPWMdutycycle(PWM_PIN_17, duty);
            gpioSetPWMdutycycle(PWM_PIN_18, duty);
            gpioSetPWMdutycycle(PWM_PIN_27, duty);
            sleep(1); // Wait for 1 second
        }
        for (int duty = 100; duty >= 0; duty--) {
            gpioSetPWMdutycycle(PWM_PIN_4, duty);
            gpioSetPWMdutycycle(PWM_PIN_17, duty);
            gpioSetPWMdutycycle(PWM_PIN_18, duty);
            gpioSetPWMdutycycle(PWM_PIN_27, duty);
            sleep(1); // Wait for 1 second
        }
        sleep(60); // Wait for 60 seconds
    }

    printf("Exiting PWM output\n");

    // Clean up
    gpioSetPWMdutycycle(PWM_PIN_4, 0);
    gpioSetPWMdutycycle(PWM_PIN_17, 0);
    gpioSetPWMdutycycle(PWM_PIN_18, 0);
    gpioSetPWMdutycycle(PWM_PIN_27, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

