#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_FREQ 1000 // Frequency in Hz
#define PWM_DUTY_CYCLE 50 // Duty cycle in percentage

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    // Set up PWM channels
    for (int i = 17; i <= 25; i++) {
        if (gpioSetMode(i, PI_OUTPUT)) {
            fprintf(stderr, "Failed to set mode for GPIO %d\n", i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(i, PWM_DUTY_CYCLE)) {
            fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sa.sa_flags = 0;
    if (sigemptyset(&sa.sa_mask) != 0) {
        fprintf(stderr, "Failed to clear signal mask\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (int i = 17; i <= 25; i++) {
            printf("GPIO %d: %d%%\n", i, PWM_DUTY_CYCLE);
            usleep(50000); // Sleep for 0.05 seconds
        }
    }

    // Clean up
    for (int i = 17; i <= 25; i++) {
        if (gpioPWM(i, 0)) {
            fprintf(stderr, "Failed to set PWM duty cycle to 0 for GPIO %d\n", i);
        }
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

