#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT_PIN 4
#define DHT_GPIO 17
#define BUFFER_SIZE 50
#define MAX_READS 3

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value, reads = 0;
    char buffer[BUFFER_SIZE];
    double humidity, temperature;

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the line as output
    if (gpiod_line_request_output(line, "dht22", 0)) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the line high for 18 milliseconds
    if (gpiod_line_set_value(line, 1)) {
        perror("Failed to set GPIO line high");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    usleep(18000);

    // Set the line low for 40 microseconds
    if (gpiod_line_set_value(line, 0)) {
        perror("Failed to set GPIO line low");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    usleep(40000);

    // Read the response from the DHT22
    while (reads < MAX_READS) {
        value = gpiod_line_get_value(line);
        if (value == -1) {
            perror("Failed to read GPIO line");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Wait for the next bit
        usleep(50);

        // Read the next bit
        value = gpiod_line_get_value(line);
        if (value == -1) {
            perror("Failed to read GPIO line");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Store the bit in the buffer
        buffer[reads] = value;
        reads++;
    }

    // Release the line
    gpiod_line_release(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    // Check the validity of the reading
    if (buffer[0] != 0 || buffer[1] != 1 || buffer[2] != 1 || buffer[3] != 0 || buffer[4] != 1) {
        fprintf(stderr, "Invalid reading\n");
        return EXIT_FAILURE;
    }

    // Calculate the humidity and temperature
    humidity = ((buffer[0] << 8) | buffer[1]) / 10.0;
    temperature = ((buffer[2] << 8) | buffer[3]) / 10.0;

    // Print the results
    printf("Humidity: %.2f%%\n", humidity);
    printf("Temperature: %.2f°C\n", temperature);

    return EXIT_SUCCESS;
}

