#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define MAX31855_REG_CONFIG 0x01
#define MAX31855_REG_TEMP 0x00

void spi_init(int *fd) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));

    // Open the SPI device
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode
    tr.tx_buf = (unsigned long)NULL;
    tr.rx_buf = (unsigned long)NULL;
    tr.len = 0;
    tr.speed_hz = 500000; // 500 kHz
    tr.bits_per_word = 8;
    tr.cs_change = 0;

    if (ioctl(*fd, SPI_IOC_WR_MODE, &tr.mode) < 0) {
        perror("Failed to set SPI mode");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void spi_close(int fd) {
    close(fd);
}

int read_max31855(int fd) {
    struct spi_ioc_transfer tr[2];
    unsigned char tx[2] = {MAX31855_REG_TEMP};
    unsigned char rx[4];

    memset(&tr, 0, sizeof(tr));

    // Transfer register address
    tr[0].tx_buf = (unsigned long)&tx[0];
    tr[0].rx_buf = (unsigned long)NULL;
    tr[0].len = 1;
    tr[0].speed_hz = 500000;
    tr[0].bits_per_word = 8;
    tr[0].cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE, tr) < 0) {
        perror("Failed to send register address");
        return -1;
    }

    // Transfer temperature data
    tr[1].tx_buf = (unsigned long)NULL;
    tr[1].rx_buf = (unsigned long)&rx[0];
    tr[1].len = 4;
    tr[1].speed_hz = 500000;
    tr[1].bits_per_word = 8;
    tr[1].cs_change = 1;

    if (ioctl(fd, SPI_IOC_MESSAGE, tr) < 0) {
        perror("Failed to receive temperature data");
        return -1;
    }

    // Check if the device is present
    if ((rx[0] & 0x80) != 0) {
        fprintf(stderr, "Device is not present\n");
        return -1;
    }

    // Extract the temperature value
    int temp_raw = (rx[0] << 16) | (rx[1] << 8) | rx[2];
    float temp_celsius = (temp_raw >> 4) * 0.25;

    printf("Temperature: %.2f°C\n", temp_celsius);

    return 0;
}

void handle_interrupt(int signum) {
    printf("Interrupt received, exiting...\n");
    spi_close(fd);
    exit(EXIT_SUCCESS);
}

int main() {
    int fd;
    signal(SIGINT, handle_interrupt);

    spi_init(&fd);

    if (read_max31855(fd) < 0) {
        exit(EXIT_FAILURE);
    }

    spi_close(fd);

    return EXIT_SUCCESS;
}

