#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define TIMEOUT_MS 5000

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int fd_trigger, fd_echo;
    struct gpiod_chip *chip;
    struct gpiod_line *line_trigger, *line_echo;
    struct timespec start_time, end_time;
    long duration_us;
    double distance_cm;
    int result;

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the line objects for the trigger and echo pins
    line_trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    line_echo = gpiod_chip_get_line(chip, ECHO_PIN);

    // Request the lines for output and input
    result = gpiod_line_request_output(line_trigger, "trigger", 0);
    if (result < 0) {
        perror("Failed to request trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    result = gpiod_line_request_input(line_echo, "echo");
    if (result < 0) {
        perror("Failed to request echo line");
        gpiod_line_release(line_trigger);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Send a pulse to trigger the sensor
    gpiod_line_set_value(line_trigger, 1);
    usleep(10); // Wait for 10 microseconds
    gpiod_line_set_value(line_trigger, 0);

    // Wait for the echo pin to go high
    while (gpiod_line_get_value(line_echo) == 0) {
        if (should_exit) {
            gpiod_line_release(line_trigger);
            gpiod_line_release(line_echo);
            gpiod_chip_close(chip);
            return EXIT_SUCCESS;
        }
        usleep(10);
    }

    // Record the start time
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Wait for the echo pin to go low
    while (gpiod_line_get_value(line_echo) == 1) {
        if (should_exit) {
            gpiod_line_release(line_trigger);
            gpiod_line_release(line_echo);
            gpiod_chip_close(chip);
            return EXIT_SUCCESS;
        }
        usleep(10);
    }

    // Record the end time
    clock_gettime(CLOCK_MONOTONIC, &end_time);

    // Calculate the duration of the pulse
    duration_us = (end_time.tv_sec - start_time.tv_sec) * 1000000 +
                  (end_time.tv_nsec - start_time.tv_nsec) / 1000;

    // Calculate the distance in centimeters
    distance_cm = duration_us / 58.2;

    // Print the distance
    printf("Distance: %.2f cm\n", distance_cm);

    // Release the lines and close the chip
    gpiod_line_release(line_trigger);
    gpiod_line_release(line_echo);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

