    if (ret < 0) {
        perror("Failed to request GPIO line input");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        return EXIT_FAILURE;
    }

    // Check if the BME280 is present
    uint8_t id[2];
    ret = i2c_smbus_read_i2c_block_data(i2c_fd, 0xD0, 2, id);
    if (ret != 2 || id[0] != 0x60 || id[1] != 0x01) {
        fprintf(stderr, "BME280 not found at address 0x%02X\n", BME280_I2C_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BME280 found at address 0x%02X\n", BME280_I2C_ADDR);

    // Read temperature, pressure, and humidity
    for (int i = 0; i < 3; ++i) {
        uint8_t data[24];
        ret = i2c_smbus_read_i2c_block_data(i2c_fd, 0xF7, 24, data);
        if (ret != 24) {
            fprintf(stderr, "Failed to read data from BME280\n");
            cleanup();
            return EXIT_FAILURE;
        }

        // Process the data to extract temperature, pressure, and humidity
        // This is a simplified example and assumes the data is correctly formatted
        float temperature = ((data[0] << 16) | (data[1] << 8) | data[2]) / 100.0f;
        float pressure = ((data[3] << 16) | (data[4] << 8) | data[5]) / 256.0f;
        float humidity = ((data[6] << 16) | (data[7] << 8) | data[8]) / 1024.0f;

        printf("Temperature: %.2f°C, Pressure: %.2f hPa, Humidity: %.2f%%\n",
               temperature, pressure, humidity);

        // Wait for 5 seconds before the next reading
        sleep(5);
    }

    // Release resources
    cleanup();

    return EXIT_SUCCESS;
}

