#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT 1000000 // Timeout in microseconds

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    int trigger_value, echo_value;
    long duration;
    double distance;
    struct timespec sleep_time;

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines as outputs and inputs respectively
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Failed to request trigger line as output");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Failed to request echo line as input");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (keep_running) {
        // Send a pulse to the trigger pin
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for the echo pin to go high
        while ((echo_value = gpiod_line_get_value(echo_line)) == 0) {
            if (--TIMEOUT <= 0) {
                fprintf(stderr, "Timeout waiting for echo\n");
                break;
            }
            nanosleep(&sleep_time, NULL);
        }

        // Measure the duration of the pulse
        if (echo_value) {
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            while ((echo_value = gpiod_line_get_value(echo_line)) != 0) {
                if (--TIMEOUT <= 0) {
                    fprintf(stderr, "Timeout waiting for echo\n");
                    break;
                }
                nanosleep(&sleep_time, NULL);
            }
            clock_gettime(CLOCK_MONOTONIC, &end_time);

            duration = (end_time.tv_sec - start_time.tv_sec) * 1000000 +
                       (end_time.tv_nsec - start_time.tv_nsec) / 1000;

            // Calculate distance in centimeters
            distance = duration * 0.0343 / 2;
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Echo not detected\n");
        }

        // Sleep for 0.5 seconds
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000;
        nanosleep(&sleep_time, NULL);
    }

    // Release resources
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

