    // Register signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to change duty cycle every 0.1 seconds
    while (1) {
        duty_cycle = (duty_cycle + 1) % 101; // Cycle through 0-100%
        if (gpioPWM(gpio_handle, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }
        sleep(0.1);
    }

    // Clean up resources
    gpioUnexport(gpio_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

