#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_4 4
#define PWM_PIN_22 22

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    // Set up PWM on GPIO 4 and 22
    if (gpioSetMode(PWM_PIN_4, PI_OUTPUT) != PI_OK || gpioSetMode(PWM_PIN_22, PI_OUTPUT)) {
        fprintf(stderr, "Failed to set mode for GPIO\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_4, 500) != PI_OK || gpioSetPWMfrequency(PWM_PIN_22, 500)) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_4, 1023) != PI_OK || gpioSetPWMrange(PWM_PIN_22, 1023)) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sa.sa_flags = 0;
    if (sigemptyset(&sa.sa_mask) != 0 || sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Apply different PWM values to GPIO 4 and 22
        int pwm_value_4 = rand() % 1024;
        int pwm_value_22 = rand() % 1024;
