        // Report the current PWM values
        printf("PWM 4: %d, PWM 22: %d\n", pwm_value_4, pwm_value_22);

        // Wait for 0.01 seconds
        usleep(100000);
    }

    // Clean up and terminate pigpio
    gpioTerminate();

    return EXIT_SUCCESS;
}

