#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    unsigned int value;
    struct timespec start, end;
    double duration, distance;

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the trigger and echo lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    // Request the trigger line for output
    ret = gpiod_line_request_output(trigger_line, "HC-SR04_trigger", 0);
    if (ret) {
        perror("Failed to request trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the echo line for input
    ret = gpiod_line_request_input(echo_line, "HC-SR04_echo");
    if (ret) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Trigger the sensor
        gpiod_line_set_value(trigger_line, 1);
        usleep(10); // Wait for 10 microseconds
        gpiod_line_set_value(trigger_line, 0);

        // Wait for the echo to start
        while (gpiod_line_get_value(echo_line) == 0) {
            if (should_exit) {
                break;
            }
        }

        // Record the start time
        clock_gettime(CLOCK_MONOTONIC, &start);

        // Wait for the echo to stop
        while (gpiod_line_get_value(echo_line) == 1) {
            if (should_exit) {
                break;
            }
        }

        // Record the end time
        clock_gettime(CLOCK_MONOTONIC, &end);

        // Calculate the duration of the pulse
        duration = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
        if (duration < 0.000001) {
            printf("Distance: Out of range\n");
        } else {
            // Calculate the distance in centimeters
            distance = duration * 17150;
            printf("Distance: %.2f cm\n", distance);
        }

        // Sleep for a short period before the next measurement
        usleep(1000000); // 1 second
    }

    // Release the lines and close the chip
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

