    keep_running = 0;
}

int main() {
    int result;

    // Initialize pigpio library
    result = gpioInitialise();
    if (result < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioErrDescription(result));
        return EXIT_FAILURE;
    }

    // Set up PWM pins
    result = gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    if (result < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d: %s\n", PWM_PIN_2, gpioErrDescription(result));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    result = gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    if (result < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d: %s\n", PWM_PIN_3, gpioErrDescription(result));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    result = gpioSetMode(PWM_PIN_18, PI_OUTPUT);
    if (result < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d: %s\n", PWM_PIN_18, gpioErrDescription(result));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set PWM frequency and duty cycle
    result = gpioPWM(PWM_PIN_2, 500); // 500 Hz, 50% duty cycle
    if (result < 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", PWM_PIN_2, gpioErrDescription(result));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    result = gpioPWM(PWM_PIN_3, 1000); // 1000 Hz, 100% duty cycle
    if (result < 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", PWM_PIN_3, gpioErrDescription(result));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    result = gpioPWM(PWM_PIN_18, 2000); // 2000 Hz, 200% duty cycle
    if (result < 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", PWM_PIN_18, gpioErrDescription(result));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    while (keep_running) {
        printf("PWM State: 2: 500 Hz, 3: 1000 Hz, 18: 2000 Hz\n");
        sleep(5);
    }

    // Clean up
    gpioTerminate();

    return EXIT_SUCCESS;
}

