    gpiod_line_set_value(line_trigger, 0);

    // Wait for the echo pin to go high
    while (gpiod_line_get_value(line_echo) == 0 && !should_exit) {
        if (clock_gettime(CLOCK_MONOTONIC, &start) != 0) {
            perror("Failed to get monotonic clock time");
            gpiod_line_release(line_trigger);
            gpiod_line_release(line_echo);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Wait for the echo pin to go low
    while (gpiod_line_get_value(line_echo) == 1 && !should_exit) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
            perror("Failed to get monotonic clock time");
            gpiod_line_release(line_trigger);
            gpiod_line_release(line_echo);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Calculate the duration of the pulse
    duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    // Calculate the distance in centimeters
    distance_cm = duration_us / 58.2;

    // Print the distance
    printf("Distance: %.2f cm\n", distance_cm);

    // Release the lines and close the chip
    gpiod_line_release(line_trigger);
    gpiod_line_release(line_echo);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

