#include <signal.h>
#include <pigpio.h>

// Global variable to store the handle to the GPIO pin
int gpio_handle = -1;

// Signal handler to clean up resources on interrupt
void signal_handler(int signum) {
    if (gpio_handle != -1) {
        gpioTerminate();
    }
    printf("Program terminated by signal %d\n", signum);
    exit(EXIT_SUCCESS);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO 18 as an output
    gpio_handle = gpioExport(18, PI_OUTPUT);
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to export GPIO 18\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set initial PWM frequency and duty cycle
    int freq = 50; // 50 Hz
    int duty_cycle = 50; // 50% duty cycle

    // Set PWM frequency and duty cycle
    if (gpioSetPWMfrequency(gpio_handle, freq) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMdutyCycle(gpio_handle, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to change duty cycle every 0.2 seconds
    while (1) {
        duty_cycle += 10; // Increase duty cycle by 10%
        if (duty_cycle > 100) {
            duty_cycle = 10; // Reset duty cycle to 10%
        }
        if (gpioSetPWMdutyCycle(gpio_handle, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }
        sleep(0.2); // Wait for 0.2 seconds
    }

    // Clean up resources
    gpioTerminate();

    return EXIT_SUCCESS;
}

